passing_property:
// Y matches the implemented NOT/OR/NAND/BUF function.
    check_output_function: assert property (
        @(posedge clk) Y == ~((~B1_N) & (A1 | A2))
    );

// A high B1_N forces Y high.
    check_b1n_high_forces_y_high: assert property (
        @(posedge clk) (B1_N == 1'b1) |-> (Y == 1'b1)
    );

// A1 high with B1_N high forces Y high.
    check_a1_high_with_b1n_high_forces_y_high: assert property (
        @(posedge clk) ((A1 == 1'b1) && (B1_N == 1'b1)) |-> (Y == 1'b1)
    );

// A2 high with B1_N high forces Y high.
    check_a2_high_with_b1n_high_forces_y_high: assert property (
        @(posedge clk) ((A2 == 1'b1) && (B1_N == 1'b1)) |-> (Y == 1'b1)
    );

// y must match the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) y == ((~sel & a) | (sel & b))
    );

// When sel is low, y must follow a.
    check_select_low_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (y == a)
    );

// When sel is high, y must follow b.
    check_select_high_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (y == b)
    );

// If both inputs are low, y must be low.
    check_both_inputs_low: assert property (
        @(posedge clk) ((a == 1'b0) && (b == 1'b0)) |-> (y == 1'b0)
    );

// If both inputs are high, y must be high.
    check_both_inputs_high: assert property (
        @(posedge clk) ((a == 1'b1) && (b == 1'b1)) |-> (y == 1'b1)
    );

// If a is low and b is high, y must match sel.
    check_low_high_inputs: assert property (
        @(posedge clk) ((a == 1'b0) && (b == 1'b1)) |-> (y == sel)
    );

// If a is high and b is low, y must match inverted sel.
    check_high_low_inputs: assert property (
        @(posedge clk) ((a == 1'b1) && (b == 1'b0)) |-> (y == ~sel)
    );

// Reset forces the counter to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |-> (q == 4'b0000)
    );

// When enabled, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (q == ($past(q) + 4'd1))
    );

// When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (q == $past(q))
    );

// The counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (q == 4'hF)) |=> (q == 4'h0)
    );

// X must equal A gated by SLEEP_B.
    check_x_matches_gated_input: assert property (
        @(posedge clk) X == (SLEEP_B & A)
    );

// When SLEEP_B is low, X must be low.
    check_sleep_low_forces_x_low: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When SLEEP_B is high, X must equal A.
    check_sleep_high_passes_a: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// A high X requires SLEEP_B to be high.
    check_x_high_requires_sleep_high: assert property (
        @(posedge clk) X |-> SLEEP_B
    );

// A high X requires A to be high.
    check_x_high_requires_a_high: assert property (
        @(posedge clk) X |-> A
    );

// Y matches the implemented NOR-of-ANDs function.
    check_y_matches_nor_of_ands: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force the NOR output low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> !Y
    );

// B1 and B2 high together force the NOR output low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// With no active NOR input term, Y must be high.
    check_no_active_term_drives_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 & A2) && !(B1 & B2)) |-> Y
    );

// A high Y means the C1 term is not active.
    check_y_high_excludes_c1_term: assert property (
        @(posedge clk) Y |-> !C1
    );

// A high Y means the A1/A2 term is not active.
    check_y_high_excludes_a_pair_term: assert property (
        @(posedge clk) Y |-> !(A1 & A2)
    );

// A high Y means the B1/B2 term is not active.
    check_y_high_excludes_b_pair_term: assert property (
        @(posedge clk) Y |-> !(B1 & B2)
    );

// Y must equal the 4-input NOR of A, B, C, and D.
    check_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D)
    );

// All inputs low must drive Y high.
    check_all_inputs_low_drive_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

// A high must force Y low.
    check_a_high_forces_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high must force Y low.
    check_b_high_forces_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C high must force Y low.
    check_c_high_forces_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D high must force Y low.
    check_d_high_forces_low: assert property (
        @(posedge clk) D |-> !Y
    );

// Y high implies all inputs are low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

// Y low implies at least one input is high.
    check_y_low_implies_some_input_high: assert property (
        @(posedge clk) !Y |-> (A || B || C || D)
    );

// b1x equals e[5:0] XOR k[5:0].
    check_b1x_xor: assert property (
        @(posedge CLK) b1x == (e[5:0] ^ k[5:0])
    );

// b2x equals e[11:6] XOR k[11:6].
    check_b2x_xor: assert property (
        @(posedge CLK) b2x == (e[11:6] ^ k[11:6])
    );

// b3x equals e[17:12] XOR k[17:12].
    check_b3x_xor: assert property (
        @(posedge CLK) b3x == (e[17:12] ^ k[17:12])
    );

// b4x equals e[23:18] XOR k[23:18].
    check_b4x_xor: assert property (
        @(posedge CLK) b4x == (e[23:18] ^ k[23:18])
    );

// b5x equals e[29:24] XOR k[29:24].
    check_b5x_xor: assert property (
        @(posedge CLK) b5x == (e[29:24] ^ k[29:24])
    );

// b6x equals e[35:30] XOR k[35:30].
    check_b6x_xor: assert property (
        @(posedge CLK) b6x == (e[35:30] ^ k[35:30])
    );

// b7x equals e[41:36] XOR k[41:36].
    check_b7x_xor: assert property (
        @(posedge CLK) b7x == (e[41:36] ^ k[41:36])
    );

// b8x equals e[47:42] XOR k[47:42].
    check_b8x_xor: assert property (
        @(posedge CLK) b8x == (e[47:42] ^ k[47:42])
    );

// Concatenation of b1x..b8x equals e XOR k.
    check_concatenation: assert property (
        @(posedge CLK) {b8x, b7x, b6x, b5x, b4x, b3x, b2x, b1x} == (e ^ k)
    );

// Output must match the OR of all four inputs.
    check_output_matches_or: assert property (
        @(posedge clk) output1 == (input1 | input2 | input3 | input4)
    );

// If any input is high, the output must be high.
    check_any_input_high_sets_output: assert property (
        @(posedge clk) (input1 | input2 | input3 | input4) |-> output1
    );

// If all inputs are low, the output must be low.
    check_all_inputs_low_clear_output: assert property (
        @(posedge clk) !(input1 | input2 | input3 | input4) |-> !output1
    );

// A high output requires at least one high input.
    check_output_high_requires_some_input_high: assert property (
        @(posedge clk) output1 |-> (input1 | input2 | input3 | input4)
    );

// Reset clears the counter and the output on the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk) reset |=> (count == 4'h0 && out == 1'b0)
    );

// The counter increments by one when reset is low.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// The counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset) (count == 4'hF) |=> (count == 4'h0)
    );

// The output toggles when reset is low.
    check_out_toggles: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (out == ~$past(out))
    );

// Reset drives count to zero on the next clock.
  check_reset_clears_count: assert property (
    @(posedge clk) reset |=> (count == {N{1'b0}})
  );

// If reset is held across consecutive clocks, count remains zero.
  check_reset_held_keeps_zero: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (count == {N{1'b0}})
  );

// If reset is held across consecutive clocks, count does not increment.
  check_reset_held_no_increment: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (count == $past(count))
  );

// serial_out is always the LSB of parallel_out.
    check_serial_out_matches_lsb: assert property (
        @(posedge clk) serial_out == parallel_out[0]
    );

// parallel_load captures data_in into parallel_out.
    check_parallel_load_updates_register: assert property (
        @(posedge clk) parallel_load |=> (parallel_out == $past(data_in))
    );

// parallel_load has priority over shift_dir.
    check_parallel_load_priority: assert property (
        @(posedge clk) (parallel_load && shift_dir) |=> (parallel_out == $past(data_in))
    );

// shift_dir=1 rotates the register left and inserts 0 into bit 0.
    check_left_shift_update: assert property (
        @(posedge clk) (!parallel_load && shift_dir) |=> (parallel_out == { $past(parallel_out[6:0]), 1'b0 })
    );

// shift_dir=0 rotates the register right and inserts 0 into bit 7.
    check_right_shift_update: assert property (
        @(posedge clk) (!parallel_load && !shift_dir) |=> (parallel_out == { 1'b0, $past(parallel_out[7:1]) })
    );

// Reset forces the registered output to zero on the next clock.
    check_reset_clears_output: assert property (
        @(posedge w_clock) w_reset |=> (r_bus_addr_out == 8'h00)
    );

// With reset low, the output captures the input on the next clock.
    check_capture_on_no_reset: assert property (
        @(posedge w_clock) disable iff (w_reset) 1'b1 |=> (r_bus_addr_out == $past(w_bus_addr_in))
    );

// The output always matches the input from the previous clock edge.
    check_output_matches_previous_input: assert property (
        @(posedge w_clock) 1'b1 |=> (r_bus_addr_out == $past(w_bus_addr_in))
    );

// X must match the implemented OR-then-AND function.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2) & B1 & C1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// Both A inputs low force X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// X high requires B1 and C1 high.
    check_x_high_requires_b1_and_c1: assert property (
        @(posedge clk) X |-> (B1 && C1)
    );

// X high requires at least one A input high.
    check_x_high_requires_a1_or_a2: assert property (
        @(posedge clk) X |-> (A1 || A2)
    );

// A1 high with B1 and C1 high drives X high.
    check_a1_with_b1_c1_drives_x_high: assert property (
        @(posedge clk) (A1 && B1 && C1) |-> X
    );

// A2 high with B1 and C1 high drives X high.
    check_a2_with_b1_c1_drives_x_high: assert property (
        @(posedge clk) (A2 && B1 && C1) |-> X
    );

// Load clears the counter on the next clock.
    check_load_clears_out: assert property (
        @(posedge clk) load |=> (out == 3'b000)
    );

// Load has priority over the up/down select.
    check_load_priority_over_count: assert property (
        @(posedge clk) (load && up_down) |=> (out == 3'b000)
    );

// Count up increments the counter when load is low.
    check_count_up_increments_out: assert property (
        @(posedge clk) (!load && up_down) |=> (out == ($past(out) + 3'b001))
    );

// Count down decrements the counter when load is low.
    check_count_down_decrements_out: assert property (
        @(posedge clk) (!load && !up_down) |=> (out == ($past(out) - 3'b001))
    );

// The counter wraps from 7 up to 0.
    check_count_up_wraps_from_7_to_0: assert property (
        @(posedge clk) (!load && up_down && (out == 3'b111)) |=> (out == 3'b000)
    );

// The counter wraps from 0 down to 7.
    check_count_down_wraps_from_0_to_7: assert property (
        @(posedge clk) (!load && !up_down && (out == 3'b000)) |=> (out == 3'b111)
    );

// q reflects the previous cycle's d value.
    check_q_captures_d: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(d))
    );

// The first cycle after a 1 on d is reflected on q.
    check_q_high_after_d_high: assert property (
        @(posedge clk) d |=> q
    );

// The first cycle after a 0 on d is reflected on q.
    check_q_low_after_d_low: assert property (
        @(posedge clk) !d |=> !q
    );

// X must equal the OR of A1 and A2 gated by B1.
    check_o21a_function: assert property (
        @(posedge clk) X == ((A1 | A2) & B1)
    );

// B1 low must force X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// Both A inputs low must force X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// A1 high with B1 high must drive X high.
    check_a1_and_b1_drive_x_high: assert property (
        @(posedge clk) (A1 && B1) |-> X
    );

// A2 high with B1 high must drive X high.
    check_a2_and_b1_drive_x_high: assert property (
        @(posedge clk) (A2 && B1) |-> X
    );

// X high requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires at least one A input to be high.
    check_x_high_requires_a_input_high: assert property (
        @(posedge clk) X |-> (A1 || A2)
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// With sel[1] low, the upper mux selects the lower-mux output.
    check_sel1_low_selects_lower_path: assert property (
        @(posedge clk) (sel[1] == 1'b0) |-> (out == (sel[0] ? in1 : in0))
    );

// With sel[1] high, the upper mux selects the upper-mux output.
    check_sel1_high_selects_upper_path: assert property (
        @(posedge clk) (sel[1] == 1'b1) |-> (out == (sel[0] ? in3 : in2))
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 2'b00)
    );

// When enabled, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 2'b01))
    );

// When disabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// The counter wraps from 2'b11 back to 2'b00 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 2'b11) |=> (count == 2'b00)
    );

// When enabled, data_out captures data_in on the next clock.
    check_capture_when_enabled: assert property (
        @(posedge clk) en |=> (data_out == $past(data_in))
    );

// When disabled, data_out is driven low on the next clock.
    check_clear_when_disabled: assert property (
        @(posedge clk) !en |=> (data_out == 1'b0)
    );

// data_out always matches the previous cycle's enable and data_in.
    check_registered_function: assert property (
        @(posedge clk) 1'b1 |=> (data_out == ($past(en) ? $past(data_in) : 1'b0))
    );

// Sgn_Info must always equal the XOR of Sgn_X and Sgn_Y.
    check_xor_function: assert property (
        @(posedge clk) Sgn_Info == (Sgn_X ^ Sgn_Y)
    );

// When Sgn_X and Sgn_Y are equal, Sgn_Info must be low.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (Sgn_X == Sgn_Y) |-> (Sgn_Info == 1'b0)
    );

// When Sgn_X and Sgn_Y differ, Sgn_Info must be high.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (Sgn_X != Sgn_Y) |-> (Sgn_Info == 1'b1)
    );

// COUT is the AND of A and B.
    check_cout_is_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// SUM is the XOR of A and B.
    check_sum_is_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// The two outputs are never both high.
    check_outputs_not_both_high: assert property (
        @(posedge clk) !(COUT && SUM)
    );

// When A and B differ, COUT is low and SUM is high.
    check_different_inputs_drive_sum: assert property (
        @(posedge clk) (A != B) |-> (!COUT && SUM)
    );

// adc_cdcs_o is tied high.
    check_cdcs_tied_high: assert property (
        @(posedge adc_clk) disable iff (adc_rst_i)
        (adc_cdcs_o == 1'b1)
    );

// adc_clk_source is tied to 2'b10.
    check_clk_source_tied_value: assert property (
        @(posedge adc_clk) disable iff (adc_rst_i)
        (adc_clk_source == 2'b10)
    );

// adc_dat_a_o[12] is the inverse of the previous cycle's adc_dat_a_i[12].
    check_dat_a_bit12_inverts: assert property (
        @(posedge adc_clk) disable iff (adc_rst_i)
        1'b1 |=> (adc_dat_a_o[12] == ~$past(adc_dat_a_i[12]))
    );

// adc_dat_b_o[12] is the inverse of the previous cycle's adc_dat_b_i[12].
    check_dat_b_bit12_inverts: assert property (
        @(posedge adc_clk) disable iff (adc_rst_i)
        1'b1 |=> (adc_dat_b_o[12] == ~$past(adc_dat_b_i[12]))
    );

// adc_dat_a_o[11:0] is the bitwise inverse of the previous cycle's adc_dat_a_i[11:0].
    check_dat_a_low_bits_invert: assert property (
        @(posedge adc_clk) disable iff (adc_rst_i)
        1'b1 |=> (adc_dat_a_o[11:0] == ~$past(adc_dat_a_i[11:0]))
    );

// adc_dat_b_o[11:0] is the bitwise inverse of the previous cycle's adc_dat_b_i[11:0].
    check_dat_b_low_bits_invert: assert property (
        @(posedge adc_clk) disable iff (adc_rst_i)
        1'b1 |=> (adc_dat_b_o[11:0] == ~$past(adc_dat_b_i[11:0]))
    );

// If no bits are selected, out must be 0.
    check_no_selected_bits_sets_out_to_zero: assert property (
        @(posedge clk)
        !(a[0] & b) && !(a[1] & b) && !(a[2] & b) && !(a[3] & b) |-> (out == 8'd0)
    );

// Reset clears the register on the next clock.
    check_reset_clears_register: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

// Parallel load captures parallel_input when shift controls are inactive.
    check_parallel_load: assert property (
        @(posedge clk) disable iff (reset)
        parallel_load |=> (q == $past(parallel_input))
    );

// Shift left moves bits [2:0] into [3:1] and inserts 0 in bit [0].
    check_shift_left: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && shift_left) |=> (q == {$past(q[2:0]), 1'b0})
    );

// Shift right moves bits [3:1] into [2:0] and inserts 0 in bit [3].
    check_shift_right: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && !shift_left && shift_right) |=> (q == {1'b0, $past(q[3:1])})
    );

// The register holds its value when no control is active.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && !shift_left && !shift_right) |=> (q == $past(q))
    );

// Parallel load has priority over shift_left.
    check_parallel_load_priority: assert property (
        @(posedge clk) disable iff (reset)
        (parallel_load && shift_left) |=> (q == $past(parallel_input))
    );

// Parallel load has priority over shift_right.
    check_parallel_load_priority_over_shift_right: assert property (
        @(posedge clk) disable iff (reset)
        (parallel_load && !shift_left && shift_right) |=> (q == $past(parallel_input))
    );

// 00 decodes to out0 high and the others low.
    check_decode_00: assert property (
        @(posedge clk) (in == 2'b00) |-> (out0 == 1'b1 && out1 == 1'b0 && out2 == 1'b0 && out3 == 1'b0)
    );

// 01 decodes to out1 high and the others low.
    check_decode_01: assert property (
        @(posedge clk) (in == 2'b01) |-> (out0 == 1'b0 && out1 == 1'b1 && out2 == 1'b0 && out3 == 1'b0)
    );

// 10 decodes to out2 high and the others low.
    check_decode_10: assert property (
        @(posedge clk) (in == 2'b10) |-> (out0 == 1'b0 && out1 == 1'b0 && out2 == 1'b1 && out3 == 1'b0)
    );

// 11 decodes to out3 high and the others low.
    check_decode_11: assert property (
        @(posedge clk) (in == 2'b11) |-> (out0 == 1'b0 && out1 == 1'b0 && out2 == 1'b0 && out3 == 1'b1)
    );

// The outputs are always one-hot or all low.
    check_output_onehot0: assert property (
        @(posedge clk) $onehot0({out3, out2, out1, out0})
    );

// out0 is high only for input 00.
    check_out0_only_for_00: assert property (
        @(posedge clk) out0 |-> (in == 2'b00)
    );

// out1 is high only for input 01.
    check_out1_only_for_01: assert property (
        @(posedge clk) out1 |-> (in == 2'b01)
    );

// out2 is high only for input 10.
    check_out2_only_for_10: assert property (
        @(posedge clk) out2 |-> (in == 2'b10)
    );

// out3 is high only for input 11.
    check_out3_only_for_11: assert property (
        @(posedge clk) out3 |-> (in == 2'b11)
    );

// Active-low reset forces pwm_out low.
    check_reset_forces_low: assert property (
        @(posedge clk) !rst_n |-> (pwm_out == 1'b0)
    );

// A sampled reset cycle leaves pwm_out low on the next clock.
    check_reset_holds_low_next_cycle: assert property (
        @(posedge clk) !rst_n |=> (pwm_out == 1'b0)
    );

// Outside reset, pwm_out toggles every active clock.
    check_toggle_every_active_cycle: assert property (
        @(posedge clk) disable iff (!rst_n) 1'b1 |=> (pwm_out == ~$past(pwm_out))
    );

// Z must always match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Z === (TE_B ? 1'b1 : A)
    );

// When TE_B is high, Z must be forced high.
    check_select_high_forces_one: assert property (
        @(posedge clk) TE_B |-> (Z === 1'b1)
    );

// When TE_B is low, Z must follow A.
    check_select_low_follows_a: assert property (
        @(posedge clk) !TE_B |-> (Z === A)
    );

// eq must match the RTL's equality comparison.
    check_eq_definition: assert property (
        @(posedge clk) eq == (a == b)
    );

// When a and b are equal, only eq can be high.
    check_eq_only_when_equal: assert property (
        @(posedge clk) (a == b) |-> (eq && !gt && !lt)
    );

// Y must match the implemented OAI21X1 equation.
    check_oai21x1_equation: assert property (
        @(posedge clk) Y == ~((A | B) & C)
    );

// When C is low, the AND term is low and Y must be high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) !C |-> Y
    );

// When both OR inputs are low, the OR term is low and Y must be high.
    check_ab_low_forces_y_high: assert property (
        @(posedge clk) (!A && !B) |-> Y
    );

// When C is high and either OR input is high, Y must be low.
    check_c_high_and_ab_high_forces_y_low: assert property (
        @(posedge clk) (C && (A || B)) |-> !Y
    );

// A low Y can only occur when C is high and at least one OR input is high.
    check_y_low_only_when_c_high_and_ab_high: assert property (
        @(posedge clk) !Y |-> (C && (A || B))
    );

// aluflags[3] is the sign bit of the computed result.
    check_aluflags_sign: assert property (
        @(posedge clk)
        aluflags[3] == aluresult[31]
    );

// aluflags[2] is asserted only when the result is zero.
    check_aluflags_zero: assert property (
        @(posedge clk)
        aluflags[2] == (aluresult == 32'd0)
    );

// Add/sub without carry-out clears aluflags[1] and sets aluflags[0].
    check_no_carry_sets_overflow_flag: assert property (
        @(posedge clk)
        ((alucontrol[0]) && ((srca + ~srcb + 32'd1) < 32'd0)) |-> (!aluflags[1] && aluflags[0])
    );

// When FSM_selector_C is high, the next state is forced to 00.
    check_clear_on_selector: assert property (
        @(posedge clk_IBUF_BUFG) FSM_selector_C |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

// When FSM_selector_C is low, the next state increments by AR modulo 4.
    check_increment_on_ar: assert property (
        @(posedge clk_IBUF_BUFG) !FSM_selector_C |=> (FSM_sequential_state_reg_reg == ($past(FSM_sequential_state_reg_reg) + $past(AR)))
    );

// A zero increment leaves the state unchanged when selector is low.
    check_zero_increment_holds: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 1'b0)) |=> (FSM_sequential_state_reg_reg == $past(FSM_sequential_state_reg_reg))
    );

// Reset clears all registered state.
    check_reset_state: assert property (
        @(posedge clk)
        !reset_n |-> ((pwm_timer == 12'd0) &&
                      (fifo_rdreq == 1'b0) &&
                      (audiodata_32 == 32'd0) &&
                      (audiodata_32_p == 32'd0) &&
                      (data_rdy == 1'b0))
    );

// op is low whenever clr is asserted.
    check_op_low_when_clr_high: assert property (
        @(posedge clk) clr |-> (op == 1'b0)
    );

// Reset clears all state and outputs.
    check_reset_state: assert property (
        @(posedge clk)
        rst |-> ((activate == 2'b00) && (data == 32'd0) && (strobe == 1'b0) && (count == 24'd0))
    );

// strobe is never asserted when activate is zero.
    check_strobe_never_when_no_activate: assert property (
        @(posedge clk) disable iff (rst)
        (activate == 2'b00) |-> (strobe == 1'b0)
    );

// Reset forces the output to the initialized value.
    check_reset_forces_init: assert property (
        @(posedge clock) reset |=> (io_out == $past(io_init))
    );

// With enable low, the output holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (reset)
        !io_enable |=> (io_out == $past(io_out))
    );

// With enable high, the output captures io_in.
    check_capture_when_enabled: assert property (
        @(posedge clock) disable iff (reset)
        io_enable |=> (io_out == $past(io_in))
    );

// g_out must equal the AND of a and b.
    check_g_out_matches_and: assert property (
        @(posedge clk) g_out == (a & b)
    );

// p_out must equal the OR of a and b.
    check_p_out_matches_or: assert property (
        @(posedge clk) p_out == (a | b)
    );

// Both outputs must be low when both inputs are low.
    check_both_low_case: assert property (
        @(posedge clk) (!a && !b) |-> (!g_out && !p_out)
    );

// Both outputs must be high when both inputs are high.
    check_both_high_case: assert property (
        @(posedge clk) (a && b) |-> (g_out && p_out)
    );

// g_out must be low when a is low.
    check_g_out_low_when_a_low: assert property (
        @(posedge clk) !a |-> !g_out
    );

// g_out must be low when b is low.
    check_g_out_low_when_b_low: assert property (
        @(posedge clk) !b |-> !g_out
    );

// p_out must be high when a is high.
    check_p_out_high_when_a_high: assert property (
        @(posedge clk) a |-> p_out
    );

// p_out must be high when b is high.
    check_p_out_high_when_b_high: assert property (
        @(posedge clk) b |-> p_out
    );

// X must equal the AND of all four inputs.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// X must be high when all inputs are high.
    check_x_high_when_all_inputs_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// X must be low when any input is low.
    check_x_low_when_any_input_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !X
    );

// A high X requires all inputs to be high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A & B & C & D)
    );

// X must equal the OR of A, B, and C.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

// X must be low when all inputs are low.
    check_all_inputs_low: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// X must be high when A is high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> X
    );

// X must be high when B is high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> X
    );

// X must be high when C is high.
    check_c_high_sets_x: assert property (
        @(posedge clk) C |-> X
    );

// out_comb must match the RTL XOR expression.
    check_out_matches_rtl_expression: assert property (
        @(posedge clk) out_comb == ((a & ~b) | (~a & b))
    );

// out_comb must equal the XOR of a and b.
    check_out_matches_xor_function: assert property (
        @(posedge clk) out_comb == (a ^ b)
    );

// When a and b are equal, out_comb must be low.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (a == b) |-> (out_comb == 1'b0)
    );

// When a and b differ, out_comb must be high.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (a != b) |-> (out_comb == 1'b1)
    );

// When A1 is high and A2 is low, Y follows B2.
    check_select_10_routes_b2: assert property (
        @(posedge clk)
        ( A1_N & ~A2_N) |-> (Y == B2)
    );

// When both select inputs are high, Y follows B1.
    check_select_11_routes_b1: assert property (
        @(posedge clk)
        ( A1_N &  A2_N) |-> (Y == B1)
    );

// op 0000 selects 16-bit addition.
    check_add_operation: assert property (
        @(posedge clk) (op == 4'b0000) |-> (Y == (A + B))
    );

// op 0001 selects 16-bit subtraction.
    check_sub_operation: assert property (
        @(posedge clk) (op == 4'b0001) |-> (Y == (A - B))
    );

// op 0010 selects bitwise AND.
    check_and_operation: assert property (
        @(posedge clk) (op == 4'b0010) |-> (Y == (A & B))
    );

// op 0011 selects bitwise OR.
    check_or_operation: assert property (
        @(posedge clk) (op == 4'b0011) |-> (Y == (A | B))
    );

// op 0100 selects bitwise XOR.
    check_xor_operation: assert property (
        @(posedge clk) (op == 4'b0100) |-> (Y == (A ^ B))
    );

// op 0101 selects bitwise NOT of A.
    check_not_a_operation: assert property (
        @(posedge clk) (op == 4'b0101) |-> (Y == (~A))
    );

// op 0110 selects logical left shift by one.
    check_shift_left_operation: assert property (
        @(posedge clk) (op == 4'b0110) |-> (Y == ({A[14:0], 1'b0}))
    );

// op 0111 selects logical right shift by one.
    check_shift_right_operation: assert property (
        @(posedge clk) (op == 4'b0111) |-> (Y == ({1'b0, A[15:1]}))
    );

// op 1000 selects rotate left by one.
    check_rotate_left_operation: assert property (
        @(posedge clk) (op == 4'b1000) |-> (Y == ({A[14:0], A[15]}))
    );

// op 1001 selects rotate right by one.
    check_rotate_right_operation: assert property (
        @(posedge clk) (op == 4'b1001) |-> (Y == ({A[0], A[15:1]}))
    );

// Any unlisted op code drives zero.
    check_default_zero_operation: assert property (
        @(posedge clk)
        ((op != 4'b0000) && (op != 4'b0001) && (op != 4'b0010) &&
         (op != 4'b0011) && (op != 4'b0100) && (op != 4'b0101) &&
         (op != 4'b0110) && (op != 4'b0111) && (op != 4'b1000) &&
         (op != 4'b1001)) |-> (Y == 16'h0000)
    );

// out_xor is the XOR of the selected input with a.
    check_out_xor_function: assert property (
        @(posedge clk)
        out_xor == ((sel_b2 ? b : (sel_b1 ? b : a)) ^ a)
    );

// out_xor_inv is the bitwise inverse of out_xor.
    check_out_xor_inv_function: assert property (
        @(posedge clk)
        out_xor_inv == ~out_xor
    );

// out_logical_inv is the logical inverse of out_xor.
    check_out_logical_inv_function: assert property (
        @(posedge clk)
        out_logical_inv == !out_xor
    );

// Output is always one-hot.
    check_out_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// Input 0000 decodes to bit 0.
    check_decode_0000: assert property (
        @(posedge clk) (in == 4'h0) |-> (out == 16'h0001)
    );

// Input 0001 decodes to bit 1.
    check_decode_0001: assert property (
        @(posedge clk) (in == 4'h1) |-> (out == 16'h0002)
    );

// Input 0010 decodes to bit 2.
    check_decode_0010: assert property (
        @(posedge clk) (in == 4'h2) |-> (out == 16'h0004)
    );

// Input 0011 decodes to bit 3.
    check_decode_0011: assert property (
        @(posedge clk) (in == 4'h3) |-> (out == 16'h0008)
    );

// Input 0100 decodes to bit 4.
    check_decode_0100: assert property (
        @(posedge clk) (in == 4'h4) |-> (out == 16'h0010)
    );

// Input 0101 decodes to bit 5.
    check_decode_0101: assert property (
        @(posedge clk) (in == 4'h5) |-> (out == 16'h0020)
    );

// Input 0110 decodes to bit 6.
    check_decode_0110: assert property (
        @(posedge clk) (in == 4'h6) |-> (out == 16'h0040)
    );

// Input 0111 decodes to bit 7.
    check_decode_0111: assert property (
        @(posedge clk) (in == 4'h7) |-> (out == 16'h0080)
    );

// Input 1000 decodes to bit 8.
    check_decode_1000: assert property (
        @(posedge clk) (in == 4'h8) |-> (out == 16'h0100)
    );

// Input 1001 decodes to bit 9.
    check_decode_1001: assert property (
        @(posedge clk) (in == 4'h9) |-> (out == 16'h0200)
    );

// Input 1010 decodes to bit 10.
    check_decode_1010: assert property (
        @(posedge clk) (in == 4'hA) |-> (out == 16'h0400)
    );

// Input 1011 decodes to bit 11.
    check_decode_1011: assert property (
        @(posedge clk) (in == 4'hB) |-> (out == 16'h0800)
    );

// Input 1100 decodes to bit 12.
    check_decode_1100: assert property (
        @(posedge clk) (in == 4'hC) |-> (out == 16'h1000)
    );

// Input 1101 decodes to bit 13.
    check_decode_1101: assert property (
        @(posedge clk) (in == 4'hD) |-> (out == 16'h2000)
    );

// Input 1110 decodes to bit 14.
    check_decode_1110: assert property (
        @(posedge clk) (in == 4'hE) |-> (out == 16'h4000)
    );

// Input 1111 decodes to bit 15.
    check_decode_1111: assert property (
        @(posedge clk) (in == 4'hF) |-> (out == 16'h8000)
    );

// out_comb_logic must equal the XOR of a and b.
    check_xor_function: assert property (
        @(posedge clk) out_comb_logic == (a ^ b)
    );

// When a and b are equal, out_comb_logic must be low.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (a == b) |-> (out_comb_logic == 1'b0)
    );

// When a and b differ, out_comb_logic must be high.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (a != b) |-> (out_comb_logic == 1'b1)
    );

// X matches the implemented OR-of-A/B/C and inverted D_N.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A | B | C | ~D_N)
    );

// A high forces X high.
    check_a_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_forces_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C high forces X high.
    check_c_forces_x_high: assert property (
        @(posedge clk) C |-> X
    );

// D_N low forces X high.
    check_dn_low_forces_x_high: assert property (
        @(posedge clk) !D_N |-> X
    );

// All low inputs make X low.
    check_all_inputs_low_drive_x_low: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> !X
    );

// X low implies A, B, and C are low and D_N is high.
    check_x_low_implies_inputs_low: assert property (
        @(posedge clk) !X |-> (!A && !B && !C && D_N)
    );

// X matches the implemented OR-of-A/B/C and inverted D_N.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A | B | C | ~D_N)
    );

// A high forces X high.
    check_a_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_forces_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C high forces X high.
    check_c_forces_x_high: assert property (
        @(posedge clk) C |-> X
    );

// D_N low forces X high.
    check_dn_low_forces_x_high: assert property (
        @(posedge clk) !D_N |-> X
    );

// All low inputs make X low.
    check_all_inputs_low_drive_x_low: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> !X
    );

// X low implies A, B, and C are low and D_N is high.
    check_x_low_implies_inputs_low: assert property (
        @(posedge clk) !X |-> (!A && !B && !C && D_N)
    );

// X must equal the AND of all four inputs.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// All inputs high must drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// A low must force X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// B low must force X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low must force X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low must force X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// Reset clears the stored output value.
    check_reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 6'h00)
    );

// Reset clears the readback data.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'h00000000)
    );

// Address 0 reads back the stored output value.
    check_read_address_zero_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'h0) |-> (readdata == {26'b0, out_port})
    );

// Nonzero addresses read zero.
    check_read_nonzero_address_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'h0) |-> (readdata == 32'h00000000)
    );

// A selected write to address 0 updates the stored output value.
    check_write_address_zero_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'h0)) |=> (out_port == $past(writedata[5:0]))
    );

// Without a selected write to address 0, the stored output value holds.
    check_no_write_address_zero_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'h0)) |=> (out_port == $past(out_port))
    );

// o_dataout follows the mux select between i_register_settings and i_datain.
    check_output_mux_function: assert property (
        @(posedge clock) disable iff (!resetn)
        o_dataout == (i_settings ? i_register_settings : i_datain)
    );

// o_dataout_valid is a direct pass-through of i_datain_valid.
    check_valid_passthrough: assert property (
        @(posedge clock) disable iff (!resetn)
        o_dataout_valid == i_datain_valid
    );

// o_datain_stall is a direct pass-through of i_dataout_stall.
    check_stall_passthrough: assert property (
        @(posedge clock) disable iff (!resetn)
        o_datain_stall == i_dataout_stall
    );

// When i_settings is high, o_dataout selects i_register_settings.
    check_select_register_settings: assert property (
        @(posedge clock) disable iff (!resetn)
        i_settings |-> (o_dataout == i_register_settings)
    );

// When i_settings is low, o_dataout selects i_datain.
    check_select_datain: assert property (
        @(posedge clock) disable iff (!resetn)
        !i_settings |-> (o_dataout == i_datain)
    );

// A high i_datain_valid is always reflected on o_dataout_valid.
    check_valid_high_when_datain_valid: assert property (
        @(posedge clock) disable iff (!resetn)
        i_datain_valid |-> o_dataout_valid
    );

// A low i_datain_valid is always reflected on o_dataout_valid.
    check_valid_low_when_datain_invalid: assert property (
        @(posedge clock) disable iff (!resetn)
        !i_datain_valid |-> !o_dataout_valid
    );

// A high i_dataout_stall is always reflected on o_datain_stall.
    check_stall_high_when_dataout_stall: assert property (
        @(posedge clock) disable iff (!resetn)
        i_dataout_stall |-> o_datain_stall
    );

// A low i_dataout_stall is always reflected on o_datain_stall.
    check_stall_low_when_dataout_not_stall: assert property (
        @(posedge clock) disable iff (!resetn)
        !i_dataout_stall |-> !o_datain_stall
    );

// X is low after a cycle with reset asserted.
    check_reset_clears_x: assert property (
        @(posedge clk) reset |=> (X == 1'b0)
    );

// X is low after a cycle where A and B are not both high.
    check_and_low_when_inputs_low: assert property (
        @(posedge clk) disable iff (reset)
        ((A == 1'b0) || (B == 1'b0)) |=> (X == 1'b0)
    );

// X is high after a cycle where A and B are both high.
    check_and_high_when_inputs_high: assert property (
        @(posedge clk) disable iff (reset)
        ((A == 1'b1) && (B == 1'b1)) |=> (X == 1'b1)
    );

// Y matches the implemented A211OI function.
    check_y_matches_a211oi_function: assert property (
        @(posedge clk) Y == ~((A1 & A2) | B1 | C1)
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force the NOR output low.
    check_a1_a2_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1 and C1 low, Y is the inverse of A1 AND A2.
    check_y_when_b1_c1_low: assert property (
        @(posedge clk) (!B1 && !C1) |-> (Y == ~(A1 & A2))
    );

// With A1 and A2 low, Y is the inverse of B1 OR C1.
    check_y_when_a1_a2_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> (Y == ~(B1 | C1))
    );

// All inputs low produce a high output.
    check_all_inputs_low_gives_y_high: assert property (
        @(posedge clk) (!A1 && !A2 && !B1 && !C1) |-> Y
    );

// All inputs high produce a low output.
    check_all_inputs_high_gives_y_low: assert property (
        @(posedge clk) (A1 && A2 && B1 && C1) |-> !Y
    );

// Active-low reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 3'b000)
    );

// The first sampled cycle after reset release still sees zero.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == 3'b000)
    );

// The first active cycle after reset release still sees zero.
    check_first_active_cycle_zero: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |=> (count == 3'b000)
    );

// The first active cycle after reset release then increments to one.
    check_first_active_cycle_one: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |=> (count == 3'b001)
    );

// The counter increments by one on each active clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count == ($past(count) + 3'b001))
    );

// The 3-bit counter wraps from 7 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst) (count == 3'b111) |=> (count == 3'b000)
    );

// CLR forces both outputs to zero on the next clock.
    check_clear_forces_zero: assert property (
        @(posedge CLK) CLR |=> (Q == 4'b0000 && Q_next == 4'b0000)
    );

// LOAD captures D into both outputs on the next clock.
    check_load_captures_d: assert property (
        @(posedge CLK) disable iff (CLR) LOAD |=> (Q == $past(D) && Q_next == $past(D))
    );

// Without LOAD, Q shifts left and inserts D[3] into bit 0.
    check_shift_updates_q: assert property (
        @(posedge CLK) disable iff (CLR) !LOAD |=> (Q == { $past(Q[2:0]), $past(D[3]) })
    );

// CLR has priority over LOAD when both are asserted.
    check_clear_overrides_load: assert property (
        @(posedge CLK) (CLR && LOAD) |=> (Q == 4'b0000 && Q_next == 4'b0000)
    );

// out_and must equal the reduction AND of in.
    check_out_and_matches_reduction_and: assert property (
        @(posedge clk) out_and == (&in)
    );

// out_and must be high when all input bits are high.
    check_out_and_high_when_all_high: assert property (
        @(posedge clk) (&in) |-> out_and
    );

// X must equal the OR of A and B.
    check_or_function: assert property (
        @(posedge clk) X == (A | B)
    );

// A high must drive X high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> X
    );

// B high must drive X high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> X
    );

// Both inputs low must drive X low.
    check_both_inputs_low_clear_x: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

// X high must come from at least one high input.
    check_x_high_has_high_input: assert property (
        @(posedge clk) X |-> (A || B)
    );

// Clear forces the output low on the next clock.
    check_clear_forces_low: assert property (
        @(posedge clk) clr |=> (op == 1'b0)
    );

// Clear has priority over clock enable when both are asserted.
    check_clear_priority_over_ce: assert property (
        @(posedge clk) (clr && ce) |=> (op == 1'b0)
    );

// Clock enable sets the output high when clear is low.
    check_ce_sets_high: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == 1'b1)
    );

// The output holds its value when neither clear nor clock enable is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (clr) (!ce) |=> (op == $past(op))
    );

// Active-low reset forces Q low and QN high.
    check_reset_state: assert property (
        @(posedge CLK) !RST |-> (Q == 1'b0 && QN == 1'b1)
    );

// Q captures D on the next clock when reset is inactive.
    check_q_captures_d: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |=> (Q == $past(D))
    );

// QN captures the inverse of D on the next clock when reset is inactive.
    check_qn_captures_not_d: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |=> (QN == ~$past(D))
    );

// Q and QN remain complementary when reset is inactive.
    check_outputs_complementary: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |-> (QN == ~Q)
    );

// X matches the implemented OR-of-AND function.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | B1 | C1)
    );

// B1 high forces X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// C1 high forces X high.
    check_c1_forces_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 high together force X high.
    check_a1_a2_force_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// With A1 and A2 low, X reduces to B1 OR C1.
    check_a1_a2_low_reduces_to_bc_or: assert property (
        @(posedge clk) (!A1 && !A2) |-> (X == (B1 | C1))
    );

// X low requires B1 and C1 low and A1/A2 not both high.
    check_x_low_condition: assert property (
        @(posedge clk) (!X) |-> (!B1 && !C1 && !(A1 && A2))
    );

// Active-low reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 4'h0)
    );

// When enabled, the counter increments by one on the next clock.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When disabled, the counter holds its value on the next clock.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
        !enable |=> (count == $past(count))
    );

// The counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'h0)
    );

// The first sampled cycle after reset deassertion still shows zero.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (count == 4'h0)
    );

// The first active cycle after reset deassertion shows count one.
    check_post_reset_first_increment: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |=> (count == 4'h1)
    );

// The counter increments by one on each active clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Reset clears the registered outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |=> (control_o == 9'b0 && pc_op == 2'b00)
    );

// When enabled, en_mem is captured into control_o[0].
    check_en_captures_en_mem: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[0] == $past(en_mem))
    );

// When enabled, should_branch is captured into control_o[1].
    check_en_captures_should_branch: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[1] == $past(should_branch))
    );

// When enabled, imm is captured into control_o[2].
    check_en_captures_imm: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[2] == $past(imm))
    );

// When enabled, pc_op selects 2'b10 for imm=1.
    check_en_selects_and_when_imm: assert property (
        @(posedge clk) disable iff (rst) (en && imm) |=> (pc_op == 2'b10)
    );

// When enabled, pc_op selects 2'b00 for imm=0.
    check_en_selects_add_when_not_imm: assert property (
        @(posedge clk) disable iff (rst) (en && !imm) |=> (pc_op == 2'b00)
    );

// When not enabled, control_o holds its previous value.
    check_hold_control_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (control_o == $past(control_o))
    );

// When not enabled, pc_op holds its previous value.
    check_hold_pc_op_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (pc_op == $past(pc_op))
    );

// Z must equal the AND of all four inputs.
    check_output_matches_and: assert property (
        @(posedge clk) Z == (A & B & C & D)
    );

// All inputs high must drive Z high.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A & B & C & D) |-> Z
    );

// A low must force Z low.
    check_a_low_forces_output_low: assert property (
        @(posedge clk) !A |-> !Z
    );

// B low must force Z low.
    check_b_low_forces_output_low: assert property (
        @(posedge clk) !B |-> !Z
    );

// C low must force Z low.
    check_c_low_forces_output_low: assert property (
        @(posedge clk) !C |-> !Z
    );

// D low must force Z low.
    check_d_low_forces_output_low: assert property (
        @(posedge clk) !D |-> !Z
    );

// sum must equal A XOR B.
    check_sum_xor: assert property (
        @(posedge clk) sum == (A ^ B)
    );

// carry_out must equal A AND B.
    check_carry_and: assert property (
        @(posedge clk) carry_out == (A & B)
    );

// Both inputs low must produce zero sum and zero carry.
    check_zero_inputs: assert property (
        @(posedge clk) (!A && !B) |-> (!sum && !carry_out)
    );

// A high and B low must produce sum high and carry low.
    check_a_high_b_low: assert property (
        @(posedge clk) (A && !B) |-> (sum && !carry_out)
    );

// A low and B high must produce sum high and carry low.
    check_a_low_b_high: assert property (
        @(posedge clk) (!A && B) |-> (sum && !carry_out)
    );

// Both inputs high must produce carry high and sum low.
    check_both_high: assert property (
        @(posedge clk) (A && B) |-> (!sum && carry_out)
    );

// High 16 bits are the zero-extended high sum.
    check_high_sum_zero_extended: assert property (
        @(posedge clk) sum[31:16] == {16'h0000, (a[31:16] + b[31:16])}
    );

// The high 16-bit sum matches the high 16 bits of the 32-bit addition.
    check_high_sum_matches_addition: assert property (
        @(posedge clk) sum[31:16] == (a[31:16] + b[31:16])
    );

// Adding one to zero on the high input increments the low input by one.
    check_high_one_plus_zero: assert property (
        @(posedge clk) ((a[31:16] == 16'h0001) && (b[31:16] == 16'h0000)) |-> (sum == {16'h0000, (a[15:0] + 16'h0001), (a[15:0] + b[15:0])})
    );

// X must equal the OR of A1 through A4 gated by B1.
    check_x_matches_o41a_function: assert property (
        @(posedge clk) X == ((A1 | A2 | A3 | A4) & B1)
    );

// B1 low must force X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// All A inputs low must force X low.
    check_all_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2 && !A3 && !A4) |-> !X
    );

// A1 high with B1 high must drive X high.
    check_a1_and_b1_drive_x_high: assert property (
        @(posedge clk) (A1 && B1) |-> X
    );

// A2 high with B1 high must drive X high.
    check_a2_and_b1_drive_x_high: assert property (
        @(posedge clk) (A2 && B1) |-> X
    );

// A3 high with B1 high must drive X high.
    check_a3_and_b1_drive_x_high: assert property (
        @(posedge clk) (A3 && B1) |-> X
    );

// A4 high with B1 high must drive X high.
    check_a4_and_b1_drive_x_high: assert property (
        @(posedge clk) (A4 && B1) |-> X
    );

// X high requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires at least one A input to be high.
    check_x_high_requires_any_a_high: assert property (
        @(posedge clk) X |-> (A1 || A2 || A3 || A4)
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

// Enable increments the counter by one when reset is low.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

// The counter holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// When SEL[1] is low, result comes from the adder path.
    check_select_add_path: assert property (
        @(posedge clk) !SEL[1] |-> (result == ((SEL[0]) ? (A - B) : (A + B)))
    );

// When SEL[1] is high, result comes from the barrel shifter path.
    check_select_shift_path: assert property (
        @(posedge clk) SEL[1] |-> (result == ((SEL[0]) ? (A >> B) : (A << B)))
    );

// With SEL[1] low and SEL[0] low, result is A plus B.
    check_add_mode: assert property (
        @(posedge clk) (!SEL[1] && !SEL[0]) |-> (result == (A + B))
    );

// With SEL[1] low and SEL[0] high, result is A minus B.
    check_sub_mode: assert property (
        @(posedge clk) (!SEL[1] && SEL[0]) |-> (result == (A - B))
    );

// With SEL[1] high and SEL[0] low, result is A left-shifted by B.
    check_left_shift_mode: assert property (
        @(posedge clk) (SEL[1] && !SEL[0]) |-> (result == (A << B))
    );

// With SEL[1] high and SEL[0] high, result is A right-shifted by B.
    check_right_shift_mode: assert property (
        @(posedge clk) (SEL[1] && SEL[0]) |-> (result == (A >> B))
    );

// ENCLK is low on the first clock after EN is low.
    check_enclk_low_after_en_low: assert property (
        @(posedge CLK) !EN |=> (ENCLK == 1'b0)
    );

// ENCLK follows TE when EN is high.
    check_enclk_follows_te_when_en_high: assert property (
        @(posedge CLK) EN |=> (ENCLK == $past(TE))
    );

// F is high for 00000 and 01111.
    check_f_high_for_00000_01111: assert property (
        @(posedge clk) (({A,B,C,D,E} == 5'b00000) || ({A,B,C,D,E} == 5'b01111)) |-> (F == 1'b1)
    );

// F is high for 11111.
    check_f_high_for_11111: assert property (
        @(posedge clk) ({A,B,C,D,E} == 5'b11111) |-> (F == 1'b1)
    );

// F is high for 10011 and 10010.
    check_f_high_for_10011_10010: assert property (
        @(posedge clk) (({A,B,C,D,E} == 5'b10011) || ({A,B,C,D,E} == 5'b10010)) |-> (F == 1'b1)
    );

// valid is deasserted on the cycle after load is deasserted.
    check_valid_deasserts_on_no_load: assert property (
        @(negedge load) 1'b1 |=> (valid == 1'b0)
    );

// Load captures data_in into the register on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (data_out == $past(data_in))
    );

// When not loading, the register shifts left and inserts 0 in bit 0.
    check_shift_behavior: assert property (
        @(posedge clk) !load |=> (data_out == {$past(data_out[2:0]), 1'b0})
    );

// Bit 3 always reflects the previous bit 2 when shifting.
    check_shift_bit3_mapping: assert property (
        @(posedge clk) !load |=> (data_out[3] == $past(data_out[2]))
    );

// Bit 2 always reflects the previous bit 1 when shifting.
    check_shift_bit2_mapping: assert property (
        @(posedge clk) !load |=> (data_out[2] == $past(data_out[1]))
    );

// Bit 1 always reflects the previous bit 0 when shifting.
    check_shift_bit1_mapping: assert property (
        @(posedge clk) !load |=> (data_out[1] == $past(data_out[0]))
    );

// Bit 0 is cleared whenever the register is not loading.
    check_shift_bit0_zero: assert property (
        @(posedge clk) !load |=> (data_out[0] == 1'b0)
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// The first sampled cycle after reset deassertion still shows zero.
