// The first active cycle after reset deassertion increments to one.
    check_post_reset_increment: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |=> (count == 4'd1)
    );

// The counter increments by one on each active clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Y matches the implemented NOR/OR/BUF function.
    check_output_function: assert property (
        @(posedge clk) Y == ((~(A1 | A2 | A3)) | (~(B1 | B2)))
    );

// A low Y means at least one A input is high and at least one B input is high.
    check_low_output_implies_a_and_b_high: assert property (
        @(posedge clk) !Y |-> (A1 || A2 || A3) && (B1 || B2)
    );

// f4 is the sum of the three submodules' outputs.
    check_f4_sum: assert property (
        @(posedge clk)
        f4_dotnamed == ((Boo_ba1 << 1) + (Boo_ba2 + b) + (Boo_ba3 - c))
    );

// If all three submodules' contributions are zero, f4 is zero.
    check_all_zero_case: assert property (
        @(posedge clk)
        ((Boo_ba1 << 1) == 4'd0) && ((Boo_ba2 + b) == 4'd0) && ((Boo_ba3 - c) == 4'd0)
        |-> (f4_dotnamed == 4'd0)
    );

// If all three submodules' contributions are one, f4 is three.
    check_all_one_case: assert property (
        @(posedge clk)
        ((Boo_ba1 << 1) == 4'd1) && ((Boo_ba2 + b) == 4'd1) && ((Boo_ba3 - c) == 4'd1)
        |-> (f4_dotnamed == 4'd3)
    );

// If the SubB and SubC contributions are zero, f4 equals the SubA contribution.
    check_subb_subc_zero_case: assert property (
        @(posedge clk)
        ((Boo_ba2 + b) == 4'd0) && ((Boo_ba3 - c) == 4'd0)
        |-> (f4_dotnamed == (Boo_ba1 << 1))
    );

// If the SubA and SubC contributions are zero, f4 equals the SubB contribution.
    check_suba_subc_zero_case: assert property (
        @(posedge clk)
        ((Boo_ba1 << 1) == 4'd0) && ((Boo_ba3 - c) == 4'd0)
        |-> (f4_dotnamed == (Boo_ba2 + b))
    );

// If the SubA and SubB contributions are zero, f4 equals the SubC contribution.
    check_suba_subb_zero_case: assert property (
        @(posedge clk)
        ((Boo_ba1 << 1) == 4'd0) && ((Boo_ba2 + b) == 4'd0)
        |-> (f4_dotnamed == (Boo_ba3 - c))
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// The first sampled cycle after reset deassertion still shows zero.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |-> (count == 4'd0)
