    );

// Enable increments the counter by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (rst) enable |=> (count == ($past(count) + 32'd1))
    );

// Disable holds the counter value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (rst) !enable |=> (count == $past(count))
    );

// Reset clears the register on the next clock.
    check_reset_clears_register: assert property (
        @(posedge clk) reset |=> (reg_0x1F == 8'h00)
    );

// A low write enable loads the input byte.
    check_write_loads_register: assert property (
