// Without load, Q holds its previous value.
    check_hold_when_not_loading: assert property (
        @(posedge clk) disable iff (reset)
        !load |=> (Q == $past(Q))
    );

// SUM must equal the three-input XOR of A, B, and CI.
    check_sum_matches_three_input_xor: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT must equal the three-input majority function of A, B, and CI.
    check_cout_matches_three_input_majority: assert property (
        @(posedge clk) COUT == ((A & B) | (B & CI) | (CI & A))
    );

// All-zero inputs must produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && !COUT)
    );

// Exactly one high input must produce sum high and carry low.
    check_one_hot_case: assert property (
        @(posedge clk)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI))
        |-> (SUM && !COUT)
    );

// Exactly two high inputs must produce sum low and carry high.
    check_two_hot_case: assert property (
        @(posedge clk)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI))
        |-> (!SUM && COUT)
    );

// All-one inputs must produce sum high and carry high.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && COUT)
    );

// Q matches the RTL next-state function.
    check_next_state_function: assert property (
        @(posedge clk)
        1'b1 |=> (Q == ($past(load) ? $past(input_data) : ($past(up_down) ? ($past(Q) + 4'd1) : ($past(Q) - 4'd1))))
    );

// Load updates Q with input_data on the next cycle.
    check_load_updates_q: assert property (
        @(posedge clk)
        load |=> (Q == $past(input_data))
    );

// With load low and up_down high, Q increments by one.
    check_increment_when_up: assert property (
        @(posedge clk)
        (!load && up_down) |=> (Q == ($past(Q) + 4'd1))
    );

// With load low and up_down low, Q decrements by one.
    check_decrement_when_down: assert property (
        @(posedge clk)
        (!load && !up_down) |=> (Q == ($past(Q) - 4'd1))
    );

// Increment wraps from 15 back to 0.
    check_increment_wraparound: assert property (
        @(posedge clk)
        (!load && up_down && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// Decrement wraps from 0 back to 15.
    check_decrement_wraparound: assert property (
        @(posedge clk)
        (!load && !up_down && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// X matches the implemented NAND/OR/AND function.
    check_output_function: assert property (
        @(posedge clk) X == ((~(A2_N & A1_N)) & (B2 | B1))
    );

// Both A inputs high force X low.
    check_a_inputs_both_high_force_low: assert property (
        @(posedge clk) (A1_N & A2_N) |-> !X
    );

// Both B inputs low force X low.
    check_b_inputs_both_low_force_low: assert property (
        @(posedge clk) (!B1 & !B2) |-> !X
    );

// A high X requires at least one B input high.
    check_high_output_requires_b_input_high: assert property (
        @(posedge clk) X |-> (B1 | B2)
    );

// Active-low reset forces COUNT to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !RST |-> (COUNT == 4'b0000)
    );

// When enabled outside reset, COUNT increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!RST) EN |-> (COUNT == ($past(COUNT) + 4'd1))
    );

// When disabled outside reset, COUNT holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!RST) !EN |-> (COUNT == $past(COUNT))
    );

// COUNT can only change when enabled outside reset.
    check_change_requires_enable: assert property (
        @(posedge clk) disable iff (!RST) (COUNT != $past(COUNT)) |-> EN
    );

// COUNT wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!RST) (EN && (COUNT == 4'hF)) |-> (COUNT == 4'h0)
    );

// Y must equal the AND of all four inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & A3 & B1 & C1)
    );

// A low A1 input must force Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A low A2 input must force Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// A low A3 input must force Y low.
    check_a3_low_forces_y_low: assert property (
        @(posedge clk) !A3 |-> !Y
    );

// A low B1 input must force Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// A low C1 input must force Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// A high Y requires all inputs to be high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A1 & A2 & A3 & B1 & C1)
    );

// X matches the RTL Boolean equation.
    check_x_matches_rtl_equation: assert property (
        @(posedge clk)
        X == ((A1 & A2 & ~B1_N) | (~A1 & (A2 | B1_N)))
    );

// When A1 is low, X reduces to B1_N OR A2.
    check_a1_low_selects_b1n_or_a2: assert property (
        @(posedge clk)
        !A1 |-> (X == (B1_N | A2))
    );

// clk_gated must equal clk AND the prior-cycle active sample.
    check_clk_gated_definition: assert property (
        @(posedge clk) 1'b1 |=> (clk_gated == (clk & $past(active)))
    );

// A low clk must force clk_gated low.
    check_clk_low_forces_clk_gated_low: assert property (
        @(posedge clk) (clk == 1'b0) |=> (clk_gated == 1'b0)
    );

// A high clk with a high prior-cycle active sample must drive clk_gated high.
    check_active_sample_high_drives_clk_gated_high: assert property (
        @(posedge clk) ((clk == 1'b1) && ($past(active) == 1'b1)) |=> (clk_gated == 1'b1)
    );

// A high clk with a low prior-cycle active sample must drive clk_gated low.
    check_active_sample_low_drives_clk_gated_low: assert property (
        @(posedge clk) ((clk == 1'b1) && ($past(active) == 1'b0)) |=> (clk_gated == 1'b0)
    );

// A1_N low and B2 high force OUT low.
    check_a1_low_b2_high_forces_low: assert property (
        @(posedge clk) (~A1_N & B2) |-> ~OUT
    );

// A2_N low and B1 high force OUT low.
    check_a2_low_b1_high_forces_low: assert property (
        @(posedge clk) (~A2_N & B1) |-> ~OUT
    );

// OUT high implies the A1_N/A2_N low term is inactive.
    check_high_out_implies_a_term_inactive: assert property (
        @(posedge clk) OUT |-> (~(~A1_N & ~A2_N))
    );

// out1 matches the implemented combinational function.
    check_out1_function: assert property (
        @(posedge clk)
        out1 == ((in1 & in2) & (in3 & in4) & (in5 & in6) & (in7 & in8) & in9)
    );

// A low in9 forces out1 low.
    check_in9_low_forces_out1_low: assert property (
        @(posedge clk)
        !in9 |-> !out1
    );

// A low in1 forces out1 low.
    check_in1_low_forces_out1_low: assert property (
        @(posedge clk)
        !in1 |-> !out1
    );

// A low in2 forces out1 low.
    check_in2_low_forces_out1_low: assert property (
        @(posedge clk)
        !in2 |-> !out1
    );

// A low in3 forces out1 low.
    check_in3_low_forces_out1_low: assert property (
        @(posedge clk)
        !in3 |-> !out1
    );

// A low in4 forces out1 low.
    check_in4_low_forces_out1_low: assert property (
        @(posedge clk)
        !in4 |-> !out1
    );

// A low in5 forces out1 low.
    check_in5_low_forces_out1_low: assert property (
        @(posedge clk)
        !in5 |-> !out1
    );

// A low in6 forces out1 low.
    check_in6_low_forces_out1_low: assert property (
        @(posedge clk)
        !in6 |-> !out1
    );

// A low in7 forces out1 low.
    check_in7_low_forces_out1_low: assert property (
        @(posedge clk)
        !in7 |-> !out1
    );

// A low in8 forces out1 low.
    check_in8_low_forces_out1_low: assert property (
        @(posedge clk)
        !in8 |-> !out1
    );

// Reset clears all address ports to their reset values.
    check_reset_clears_ports: assert property (
        @(posedge clk)
        !reset_b |-> ((address_port_0 == 8'h00) &&
                      (address_port_1 == 8'h01) &&
                      (address_port_2 == 8'h02) &&
                      (address_port_3 == 8'h03))
    );

// Read address 0 returns port 0 data.
    check_read_addr0: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd0) |-> (mem_rdata == address_port_0)
    );

// Read address 1 returns port 1 data.
    check_read_addr1: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd1) |-> (mem_rdata == address_port_1)
    );

// Read address 2 returns port 2 data.
    check_read_addr2: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd2) |-> (mem_rdata == address_port_2)
    );

// Read address 3 returns port 3 data.
    check_read_addr3: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd3) |-> (mem_rdata == address_port_3)
    );

// Write address 0 updates port 0 when enabled.
    check_write_addr0: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd0)) |=> (address_port_0 == $past(mem_wdata))
    );

// Write address 1 updates port 1 when enabled.
    check_write_addr1: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd1)) |=> (address_port_1 == $past(mem_wdata))
    );

// Write address 2 updates port 2 when enabled.
    check_write_addr2: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd2)) |=> (address_port_2 == $past(mem_wdata))
    );

// Write address 3 updates port 3 when enabled.
    check_write_addr3: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd3)) |=> (address_port_3 == $past(mem_wdata))
    );

// Without a write, port 0 holds its value.
    check_hold_addr0_without_write: assert property (
        @(posedge clk) disable iff (!reset_b)
        !(mem_en && mem_rd_wr && (mem_addr == 2'd0)) |=> (address_port_0 == $past(address_port_0))
    );

// Without a write, port 1 holds its value.
    check_hold_addr1_without_write: assert property (
        @(posedge clk) disable iff (!reset_b)
        !(mem_en && mem_rd_wr && (mem_addr == 2'd1)) |=> (address_port_1 == $past(address_port_1))
    );

// Without a write, port 2 holds its value.
    check_hold_addr2_without_write: assert property (
        @(posedge clk) disable iff (!reset_b)
        !(mem_en && mem_rd_wr && (mem_addr == 2'd2)) |=> (address_port_2 == $past(address_port_2))
    );

// Without a write, port 3 holds its value.
    check_hold_addr3_without_write: assert property (
        @(posedge clk) disable iff (!reset_b)
        !(mem_en && mem_rd_wr && (mem_addr == 2'd3)) |=> (address_port_3 == $past(address_port_3))
    );

// Reset forces the output to zero.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |-> (data_out == 8'h00)
    );

// When disabled, the next output is the previous cycle's data_in.
    check_disabled_passes_input: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (data_out == $past(data_in))
    );

// Active-low reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'h0)
    );

// The first sampled cycle after reset release still sees zero.
    check_release_from_reset_starts_at_zero: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == 4'h0)
    );

// Below 15, the counter increments by one on each clock.
    check_count_increments_below_max: assert property (
        @(posedge clk) disable iff (!rst) (count != 4'hF) |=> (count == ($past(count) + 4'd1))
    );

// At 15, the counter wraps back to zero.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Reset forces the counter to zero and clears carry.
    check_reset_state: assert property (
        @(posedge clk) rst |-> (q == 4'h0) && (carry == 1'b0)
    );

// Up count wraps from 15 to 0 and raises carry.
    check_up_wrap_carry: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b0) && (q == 4'hF) |=> (q == 4'h0) && (carry == 1'b1)
    );

// Up count increments by one below 15 and clears carry.
    check_up_increment: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b0) && (q != 4'hF) |=> (q == ($past(q) + 4'h1)) && (carry == 1'b0)
    );

// Down count wraps from 0 to 15 and raises carry.
    check_down_wrap_carry: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b1) && (q == 4'h0) |=> (q == 4'hF) && (carry == 1'b1)
    );

// Down count decrements by one above 0 and clears carry.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b1) && (q != 4'h0) |=> (q == ($past(q) - 4'h1)) && (carry == 1'b0)
    );

// Carry is high only when the previous cycle was a wrap.
    check_carry_only_on_wrap: assert property (
        @(posedge clk) disable iff (rst)
        carry |-> (($past(up_down) == 1'b0) && ($past(q) == 4'hF)) ||
                 (($past(up_down) == 1'b1) && ($past(q) == 4'h0))
    );

// Active-low reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'h0)
    );

// A load cycle updates count with data.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!rst)
        load |=> (count == $past(data))
    );

// Without load, count increments by one on the next cycle.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (!rst)
        !load |=> (count == ($past(count) + 4'h1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Clock: clk (posedge). Reset: rst_n (active-low, synchronous).
    // Sequential 16-bit up-counter with wraparound.

    // When reset is asserted low, count must be zero on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) (rst_n == 1'b0) |=> (count == 16'h0000)
    );

// When reset is asserted low, count must be zero on the same cycle.
    reset_clears_now: assert property (
        @(posedge clk) (rst_n == 1'b0) |-> (count == 16'h0000)
    );

// When not in reset, count increments by 1 on the next cycle.
    increment_when_running: assert property (
        @(posedge clk) disable iff (!rst_n) 1'b1 |=> (count == ($past(count) + 16'd1))
    );

// When not in reset, count never holds its value on the next cycle.
    no_hold_when_running: assert property (
        @(posedge clk) disable iff (!rst_n) 1'b1 |=> (count != $past(count))
    );

// When not in reset, count is always within 16-bit range on the next cycle.
    next_in_range_when_running: assert property (
        @(posedge clk) disable iff (!rst_n) 1'b1 |=> (count inside {[16'h0000:16'hFFFF]})
    );

// When not in reset, count is always within 16-bit range on the same cycle.
    current_in_range_when_running: assert property (
        @(posedge clk) disable iff (!rst_n) 1'b1 |-> (count inside {[16'h0000:16'hFFFF]})
    );

// Y matches the implemented NOT/AND/NOR/BUF logic.
    check_y_matches_logic: assert property (
        @(posedge clk) Y == ~((~B1_N) | (A1 & A2))
    );

// A low B1_N input forces Y low.
    check_b1n_low_forces_y_low: assert property (
        @(posedge clk) (B1_N == 1'b0) |-> (Y == 1'b0)
    );

// With both A inputs low, Y follows B1_N.
    check_a_inputs_low_passes_b1n: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (Y == B1_N)
    );

// When enabled, address 00000 loads 0010 on the next cycle.
    check_addr_00000_load: assert property (
        @(posedge clk) en && (addr == 5'b00000) |=> (data == 4'b0010)
    );

// When enabled, address 00001 loads 0010 on the next cycle.
    check_addr_00001_load: assert property (
        @(posedge clk) en && (addr == 5'b00001) |=> (data == 4'b0010)
    );

// When enabled, address 00010 loads 1110 on the next cycle.
    check_addr_00010_load: assert property (
        @(posedge clk) en && (addr == 5'b00010) |=> (data == 4'b1110)
    );

// When enabled, address 00011 loads 0010 on the next cycle.
    check_addr_00011_load: assert property (
        @(posedge clk) en && (addr == 5'b00011) |=> (data == 4'b0010)
    );

// When enabled, address 00100 loads 0100 on the next cycle.
    check_addr_00100_load: assert property (
        @(posedge clk) en && (addr == 5'b00100) |=> (data == 4'b0100)
    );

// When enabled, address 00101 loads 1010 on the next cycle.
    check_addr_00101_load: assert property (
        @(posedge clk) en && (addr == 5'b00101) |=> (data == 4'b1010)
    );

// When enabled, address 00110 loads 1100 on the next cycle.
    check_addr_00110_load: assert property (
        @(posedge clk) en && (addr == 5'b00110) |=> (data == 4'b1100)
    );

// When enabled, address 00111 loads 0000 on the next cycle.
    check_addr_00111_load: assert property (
        @(posedge clk) en && (addr == 5'b00111) |=> (data == 4'b0000)
    );

// When enabled, address 01000 loads 1010 on the next cycle.
    check_addr_01000_load: assert property (
        @(posedge clk) en && (addr == 5'b01000) |=> (data == 4'b1010)
    );

// When enabled, address 01001 loads 0010 on the next cycle.
    check_addr_01001_load: assert property (
        @(posedge clk) en && (addr == 5'b01001) |=> (data == 4'b0010)
    );

// When enabled, address 01010 loads 1110 on the next cycle.
    check_addr_01010_load: assert property (
        @(posedge clk) en && (addr == 5'b01010) |=> (data == 4'b1110)
    );

// When enabled, address 01011 loads 0010 on the next cycle.
    check_addr_01011_load: assert property (
        @(posedge clk) en && (addr == 5'b01011) |=> (data == 4'b0010)
    );

// When enabled, address 01100 loads 0100 on the next cycle.
    check_addr_01100_load: assert property (
        @(posedge clk) en && (addr == 5'b01100) |=> (data == 4'b0100)
    );

// When enabled, address 01101 loads 1010 on the next cycle.
    check_addr_01101_load: assert property (
        @(posedge clk) en && (addr == 5'b01101) |=> (data == 4'b1010)
    );

// When enabled, address 01110 loads 1100 on the next cycle.
    check_addr_01110_load: assert property (
        @(posedge clk) en && (addr == 5'b01110) |=> (data == 4'b1100)
    );

// When enabled, address 01111 loads 0000 on the next cycle.
    check_addr_01111_load: assert property (
        @(posedge clk) en && (addr == 5'b01111) |=> (data == 4'b0000)
    );

// When disabled, data holds its previous value.
    check_disabled_hold: assert property (
        @(posedge clk) !en |=> (data == $past(data))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

// Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 32'd0)
    );

// Enable increments the counter by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 32'd1))
    );

// Disable holds the counter value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

// 0 maps to 00000000.
    check_bcd_0_maps_to_0: assert property (
        @(posedge clk) (bcd_in == 4'd0) |-> (bin_out == 8'b00000000)
    );

// 1 maps to 00000001.
    check_bcd_1_maps_to_1: assert property (
        @(posedge clk) (bcd_in == 4'd1) |-> (bin_out == 8'b00000001)
    );

// 2 maps to 00000010.
    check_bcd_2_maps_to_2: assert property (
        @(posedge clk) (bcd_in == 4'd2) |-> (bin_out == 8'b00000010)
    );

// 3 maps to 00000011.
    check_bcd_3_maps_to_3: assert property (
        @(posedge clk) (bcd_in == 4'd3) |-> (bin_out == 8'b00000011)
    );

// 4 maps to 00000100.
    check_bcd_4_maps_to_4: assert property (
        @(posedge clk) (bcd_in == 4'd4) |-> (bin_out == 8'b00000100)
    );

// 5 maps to 00000101.
    check_bcd_5_maps_to_5: assert property (
        @(posedge clk) (bcd_in == 4'd5) |-> (bin_out == 8'b00000101)
    );

// 6 maps to 00000110.
    check_bcd_6_maps_to_6: assert property (
        @(posedge clk) (bcd_in == 4'd6) |-> (bin_out == 8'b00000110)
    );

// 7 maps to 00000111.
    check_bcd_7_maps_to_7: assert property (
        @(posedge clk) (bcd_in == 4'd7) |-> (bin_out == 8'b00000111)
    );

// 8 maps to 00001000.
    check_bcd_8_maps_to_8: assert property (
        @(posedge clk) (bcd_in == 4'd8) |-> (bin_out == 8'b00001000)
    );

// 9 maps to 00001001.
    check_bcd_9_maps_to_9: assert property (
        @(posedge clk) (bcd_in == 4'd9) |-> (bin_out == 8'b00001001)
    );

// Non-BCD inputs drive the default zero output.
    check_default_zero_for_non_bcd_inputs: assert property (
        @(posedge clk)
        ((bcd_in == 4'd10) || (bcd_in == 4'd11) || (bcd_in == 4'd12) || (bcd_in == 4'd13) ||
         (bcd_in == 4'd14) || (bcd_in == 4'd15))
        |-> (bin_out == 8'b00000000)
    );

// synch_out is the delayed input from C_NUM_STAGES clock edges later.
            check_output_matches_input_after_stages: assert property (
                @(posedge clk) 1'b1 |-> ##C_NUM_STAGES (synch_out == $past(synch_in, C_NUM_STAGES))
            );

// synch_out is never high-impedance.
            check_output_is_not_highz: assert property (
                @(posedge clk) 1'b1 |-> ##1 (synch_out !== 1'bz)
            );

// q captures data on the next cycle when load is asserted.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );

// q rotates right by two bits when enabled and not loading.
    check_rotate_when_enabled: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q == {$past(q[97:0]), $past(q[99:98])})
    );

// q holds its value when enabled and not loading.
    check_hold_when_enabled: assert property (
        @(posedge clk) (!load && (ena == 2'b00)) |=> (q == $past(q))
    );

// out_if_else is high whenever q differs from data.
    check_out_if_else_high_when_q_differs_from_data: assert property (
        @(posedge clk) (q != data) |-> (out_if_else == 1'b1)
    );

// out_if_else is low whenever q matches data.
    check_out_if_else_low_when_q_matches_data: assert property (
        @(posedge clk) (q == data) |-> (out_if_else == 1'b0)
    );

// X must equal the implemented AND/NOT function.
    check_x_matches_function: assert property (
        @(posedge clk) X == ((A1 & A2) & ~(B1 & B2))
    );

// A low A1 input forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) !A1 |-> !X
    );

// A low A2 input forces X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) !A2 |-> !X
    );

// A high X requires both A inputs high.
    check_x_high_requires_a_inputs: assert property (
        @(posedge clk) X |-> (A1 & A2)
    );

// A high X requires both B inputs low.
    check_x_high_requires_b_inputs_low: assert property (
        @(posedge clk) X |-> !(B1 & B2)
    );

// With both A inputs high and both B inputs low, X must be high.
    check_all_terms_true_sets_x_high: assert property (
        @(posedge clk) (A1 & A2 & !B1 & !B2) |-> X
    );

// X must equal the OR of A1, A2, and A3 gated by B1.
    check_o31a_function: assert property (
        @(posedge clk) X == ((A1 | A2 | A3) & B1)
    );

// B1 low must force X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// All A inputs low must force X low.
    check_all_a_low_forces_x_low: assert property (
        @(posedge clk) (!A1 && !A2 && !A3) |-> !X
    );

// A1 high with B1 high must drive X high.
    check_a1_with_b1_drives_x_high: assert property (
        @(posedge clk) (A1 && B1) |-> X
    );

// A2 high with B1 high must drive X high.
    check_a2_with_b1_drives_x_high: assert property (
        @(posedge clk) (A2 && B1) |-> X
    );

// A3 high with B1 high must drive X high.
    check_a3_with_b1_drives_x_high: assert property (
        @(posedge clk) (A3 && B1) |-> X
    );

// X high requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires at least one A input to be high.
    check_x_high_requires_any_a_high: assert property (
        @(posedge clk) X |-> (A1 || A2 || A3)
    );

// Y must equal the 4-input NOR of A, B, C, and D_N.
    check_y_matches_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D_N)
    );

// All four inputs low must drive Y high.
    check_all_inputs_low_drive_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D_N) |-> Y
    );

// A high must force Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high must force Y low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C high must force Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D_N high must force Y low.
    check_d_n_high_forces_y_low: assert property (
        @(posedge clk) D_N |-> !Y
    );

// Y high implies all four inputs are low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D_N)
    );

// Y low implies at least one input is high.
    check_y_low_implies_some_input_high: assert property (
        @(posedge clk) !Y |-> (A || B || C || D_N)
    );

// Reset clears the counter and raises precharge_safe.
    check_reset_clears_state: assert property (
        @(posedge sys_clk)
        sdram_rst |=> (counter == 3'd0 && precharge_safe == 1'b1)
    );

// Y must always match the RTL mux equation.
    check_mux_function: assert property (
        @(posedge clk) Y === (EN ? A : B)
    );

// When EN is high, Y must select A.
    check_select_a_when_enabled: assert property (
        @(posedge clk) EN |-> (Y === A)
    );

// When EN is low, Y must select B.
    check_select_b_when_disabled: assert property (
        @(posedge clk) !EN |-> (Y === B)
    );

// X must equal the OR of the two AND terms.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
    );

// A1 and A2 high must drive X high.
    check_a_term_sets_x: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// B1 and B2 high must drive X high.
    check_b_term_sets_x: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// With both AND terms low, X must be low.
    check_no_terms_clears_x: assert property (
        @(posedge clk) (!(A1 & A2) && !(B1 & B2)) |-> !X
    );

// X high must come from at least one AND term.
    check_x_high_has_source: assert property (
        @(posedge clk) X |-> ((A1 & A2) || (B1 & B2))
    );

// X low means both AND terms are low.
    check_x_low_has_no_source: assert property (
        @(posedge clk) !X |-> (!(A1 & A2) && !(B1 & B2))
    );

// The output reflects the input captured into bit 0.
    check_out_matches_input_capture: assert property (
        @(posedge shift) 1'b1 |=> (out == $past(in))
    );

// When sel is high, OUT must equal the 4-bit two's complement of A.
    check_out_equals_twos_comp_when_sel_high: assert property (
        @(posedge clk)
        sel |-> (OUT == (~A + 4'd1))
    );

// The top-level output must always be either B or the two's complement of A.
    check_out_is_b_or_twos_comp: assert property (
        @(posedge clk)
        (OUT == B) || (OUT == (~A + 4'd1))
    );

// out[0] is a direct copy of in[0].
    check_out0_passthrough: assert property (
        @(posedge clk) out[0] == in[0]
    );

// out[1] is the XOR of in[0] and in[1].
    check_out1_xor: assert property (
        @(posedge clk) out[1] == (in[0] ^ in[1])
    );

// out[2] is the XOR of in[1], in[2], and in[0].
    check_out2_xor: assert property (
        @(posedge clk) out[2] == (in[1] ^ in[2] ^ in[0])
    );

// out[3] is the XOR of in[2], in[3], and in[1].
    check_out3_xor: assert property (
        @(posedge clk) out[3] == (in[2] ^ in[3] ^ in[1])
    );

// When sel is low, out must equal a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (sel === 1'b0) |-> (out === a)
    );

// When sel is high, out must equal b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (sel === 1'b1) |-> (out === b)
    );

// If both inputs are equal, out must match that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a === b) |-> (out === a)
    );

// out must be high on the first clock after a high input.
    check_out_high_after_high_input: assert property (
        @(posedge clk) in |=> (out == 1'b1)
    );

// out must be low on the first clock after a low input.
    check_out_low_after_low_input: assert property (
        @(posedge clk) !in |=> (out == 1'b0)
    );

// A low B1 forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// X must equal A gated by SLEEP_B.
    check_x_matches_gated_input: assert property (
        @(posedge clk) X == (SLEEP_B & A)
    );

// When SLEEP_B is low, X must be low.
    check_sleep_forces_x_low: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When SLEEP_B is high, X must equal A.
    check_awake_passes_a: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// A high X requires SLEEP_B to be high.
    check_x_high_requires_awake: assert property (
        @(posedge clk) X |-> SLEEP_B
    );

// A high X requires A to be high.
    check_x_high_requires_a_high: assert property (
        @(posedge clk) X |-> A
    );

// Reset clears the accumulator output on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |=> (out == 8'h00)
    );

// The accumulator adds the previous cycle's input when reset is low.
    check_accumulator_adds_previous_input: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (out == ($past(out) + $past(data_in)))
    );

// Zero input leaves the accumulator unchanged.
    check_zero_input_holds_value: assert property (
        @(posedge clk) disable iff (rst) (data_in == 8'h00) |=> (out == $past(out))
    );

// All-ones input wraps the 8-bit accumulator.
    check_all_ones_input_wraps: assert property (
        @(posedge clk) disable iff (rst) (data_in == 8'hFF) |=> (out == ($past(out) + 8'hFF))
    );

// X matches the implemented OR-of-ANDs function.
    check_x_matches_or_of_ands: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2) | (C1 & C2))
    );

// A1 and A2 high forces X high.
    check_a_term_sets_x: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// B1 and B2 high forces X high.
    check_b_term_sets_x: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// C1 and C2 high forces X high.
    check_c_term_sets_x: assert property (
        @(posedge clk) (C1 & C2) |-> X
    );

// X can only be high when at least one product term is high.
    check_x_high_requires_some_term: assert property (
        @(posedge clk) X |-> ((A1 & A2) | (B1 & B2) | (C1 & C2))
    );

// X can only be low when all three product terms are low.
    check_x_low_requires_all_terms_low: assert property (
        @(posedge clk) !X |-> !(A1 & A2) && !(B1 & B2) && !(C1 & C2)
    );

// S[0] is the XOR of A[0], B[0], and Cin.
    check_sum_bit0_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// S[1] is the XOR of A[1], B[1], and the carry from bit 0.
    check_sum_bit1_xor_with_carry0: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
    );

// S[2] is the XOR of A[2], B[2], and the carry from bit 1.
    check_sum_bit2_xor_with_carry1: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) |
            ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
        ))
    );

// S[3] is the XOR of A[3], B[3], and the carry from bit 2.
    check_sum_bit3_xor_with_carry2: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (
            (A[2] & B[2]) |
            ((A[2] ^ B[2]) & (
                (A[1] & B[1]) |
                ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
            ))
        ))
    );

// Cout is the carry out from the final full adder.
    check_cout_from_bit3: assert property (
        @(posedge clk) Cout == (
            (A[3] & B[3]) |
            ((A[3] ^ B[3]) & (
                (A[2] & B[2]) |
                ((A[2] ^ B[2]) & (
                    (A[1] & B[1]) |
                    ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
                ))
            ))
        )
    );

// The 5-bit result matches the 4-bit addition with carry-in.
    check_full_result_matches_addition: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge CLK) reset |=> (count == 4'h0)
    );

// Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge CLK) (reset && enable) |=> (count == 4'h0)
    );

// Enable increments the counter by one when reset is low.
    check_enable_increments_count: assert property (
        @(posedge CLK) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

// The counter holds its value when enable is low.
    check_count_holds_when_disabled: assert property (
        @(posedge CLK) disable iff (reset) !enable |=> (count == $past(count))
    );

// The counter wraps from 15 back to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge CLK) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Reset clears the stored data and deasserts the output valid signal.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |-> ((out_data == 32'h00000000) && (out_valid == 1'b0))
    );

// A valid input updates the output data on the next cycle.
    check_valid_input_updates_output_data: assert property (
        @(posedge clk) disable iff (reset) in_valid |=> (out_data == $past(in_data))
    );

// A valid input sets the output valid signal on the next cycle.
    check_valid_input_sets_output_valid: assert property (
        @(posedge clk) disable iff (reset) in_valid |=> (out_valid == 1'b1)
    );

// A non-valid input clears the output valid signal on the next cycle.
    check_nonvalid_input_clears_output_valid: assert property (
        @(posedge clk) disable iff (reset) !in_valid |=> (out_valid == 1'b0)
    );

// The output data holds when no valid input is present.
    check_nonvalid_input_holds_output_data: assert property (
        @(posedge clk) disable iff (reset) !in_valid |=> (out_data == $past(out_data))
    );

// Reset clears the shift register and forces out low.
    check_reset_clears_state: assert property (
        @(posedge clk)
        rst |-> ((shiftreg == 64'h0000000000000000) && (out == 1'b0))
    );

// op 000 selects 4-bit addition.
    check_addition: assert property (
        @(posedge clk) (op == 3'b000) |-> (out == (a + b))
    );

// op 001 selects 4-bit subtraction.
    check_subtraction: assert property (
        @(posedge clk) (op == 3'b001) |-> (out == (a - b))
    );

// op 010 selects bitwise AND.
    check_and: assert property (
        @(posedge clk) (op == 3'b010) |-> (out == (a & b))
    );

// op 011 selects bitwise OR.
    check_or: assert property (
        @(posedge clk) (op == 3'b011) |-> (out == (a | b))
    );

// op 100 selects bitwise XOR.
    check_xor: assert property (
        @(posedge clk) (op == 3'b100) |-> (out == (a ^ b))
    );

// op 101 selects a left shift by one bit.
    check_shift_left: assert property (
        @(posedge clk) (op == 3'b101) |-> (out == {a[2:0], 1'b0})
    );

// op values 110 and 111 drive the default zero output.
    check_default_zero: assert property (
        @(posedge clk) ((op == 3'b110) || (op == 3'b111)) |-> (out == 4'b0000)
    );

// Reset clears the registered output on the next clock.
    check_reset_clears_output: assert property (
        @(posedge CLK) RST |=> (C == 8'h00)
    );

// In add mode, the next output is the previous cycle's A+B.
    check_add_mode_result: assert property (
        @(posedge CLK) disable iff (RST)
        (OP == 1'b0) |=> (C == ($past(A) + $past(B)))
    );

// In subtract mode, the next output is the previous cycle's A-B.
    check_subtract_mode_result: assert property (
        @(posedge CLK) disable iff (RST)
        (OP == 1'b1) |=> (C == ($past(A) - $past(B)))
    );

// In subtract mode with equal operands, the next output is zero.
    check_subtract_equal_operands_zero: assert property (
        @(posedge CLK) disable iff (RST)
        ((OP == 1'b1) && (A == B)) |=> (C == 8'h00)
    );

// EQ must match the equality comparison of A and B.
    check_eq_definition: assert property (
        @(posedge clk) EQ == (A == B)
    );

// GT must match the greater-than comparison of A and B.
    check_gt_definition: assert property (
        @(posedge clk) GT == (A > B)
    );

// LT must match the less-than comparison of A and B.
    check_lt_definition: assert property (
        @(posedge clk) LT == (A < B)
    );

// EQ and GT cannot be high together.
    check_eq_excludes_gt: assert property (
        @(posedge clk) !(EQ && GT)
    );

// EQ and LT cannot be high together.
    check_eq_excludes_lt: assert property (
        @(posedge clk) !(EQ && LT)
    );

// GT and LT cannot be high together.
    check_gt_excludes_lt: assert property (
        @(posedge clk) !(GT && LT)
    );

// Exactly one of EQ, GT, or LT must be high.
    check_output_onehot: assert property (
        @(posedge clk) $onehot({EQ, GT, LT})
    );

// overflow enable is captured when not stalled and not flushing.
    check_overflowen_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (OverflowEn_out == $past(OverflowEn))
    );

// branch address is captured when not stalled and not flushing.
    check_branch_addr_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Branch_addr_out == $past(Branch_addr))
    );

// pc add is captured when not stalled and not flushing.
    check_pc_add_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (PC_add_out == $past(PC_add))
    );

// condition is captured when not stalled and not flushing.
    check_condition_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Condition_out == $past(Condition))
    );

// branch signal is captured when not stalled and not flushing.
    check_branch_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Branch_out == $past(Branch))
    );

// pc write is captured when not stalled and not flushing.
    check_pc_write_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (PC_write_out == $past(PC_write))
    );

// memory byte write is captured when not stalled and not flushing.
    check_mem_byte_write_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Mem_Byte_Write_out == $past(Mem_Byte_Write))
    );

// rd write byte enable is captured when not stalled and not flushing.
    check_rd_write_byte_en_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Rd_Write_Byte_en_out == $past(Rd_Write_Byte_en))
    );

// memory writeback source is captured when not stalled and not flushing.
    check_memwb_src_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (MemWBSrc_out == $past(MemWBSrc))
    );

// memory data is captured when not stalled and not flushing.
    check_memdata_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (MemData_out == $past(MemData))
    );

// wb data is captured when not stalled and not flushing.
    check_wbdata_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (WBData_out == $past(WBData))
    );

// less-than result is captured when not stalled and not flushing.
    check_less_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Less_out == $past(Less))
    );

// zero result is captured when not stalled and not flushing.
    check_zero_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Zero_out == $past(Zero))
    );

// overflow result is captured when not stalled and not flushing.
    check_overflow_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Overflow_out == $past(Overflow))
    );

// rd is captured when not stalled and not flushing.
    check_rd_capture: assert property (
        @(posedge Clk) disable iff (flush)
        !stall |=> (Rd_out == $past(Rd))
    );

// out_sum must match the muxed input plus the selected position.
    check_out_sum_function: assert property (
        @(posedge clk)
        out_sum == ((sel_b1 & sel_b2) ? (b ? (3'd1 + pos) : pos) :
                    ((sel_b1 | sel_b2) ? (a ? (3'd1 + pos) : pos) : pos))
    );

// With both select bits low, the mux output is zero and out_sum is pos.
    check_out_sum_when_mux_zero: assert property (
        @(posedge clk)
        !(sel_b1 | sel_b2) |-> (out_sum == pos)
    );

// With both select bits high, the mux output is b and out_sum is b + pos.
    check_out_sum_when_mux_b: assert property (
        @(posedge clk)
        (sel_b1 & sel_b2) |-> (out_sum == (b ? (3'd1 + pos) : pos))
    );

// With only sel_b1 high, the mux output is a and out_sum is a + pos.
    check_out_sum_when_mux_a: assert property (
        @(posedge clk)
        (sel_b1 & !sel_b2) |-> (out_sum == (a ? (3'd1 + pos) : pos))
    );

// With only sel_b2 high, the mux output is a and out_sum is a + pos.
    check_out_sum_when_mux_a_when_b1_low: assert property (
        @(posedge clk)
        (!sel_b1 & sel_b2) |-> (out_sum == (a ? (3'd1 + pos) : pos))
    );

// y must always equal the OR of d0 and d1.
    check_y_matches_or: assert property (
        @(posedge clk) disable iff (clr) y == (d0 | d1)
    );

// A high d0 must force y high.
    check_d0_high_sets_y: assert property (
        @(posedge clk) disable iff (clr) d0 |-> y
    );

// A high d1 must force y high.
    check_d1_high_sets_y: assert property (
        @(posedge clk) disable iff (clr) d1 |-> y
    );

// A low d0 and d1 must force y low.
    check_both_inputs_low_clear_y: assert property (
        @(posedge clk) disable iff (clr) (!d0 && !d1) |-> !y
    );

// A high y must come from at least one high input.
    check_y_high_has_valid_cause: assert property (
        @(posedge clk) disable iff (clr) y |-> (d0 || d1)
    );

// Y matches the implemented NOR-of-ANDs function.
    check_y_matches_nor_of_ands: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces Y low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force Y low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// B1 and B2 high together force Y low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// With no active NOR input, Y must be high.
    check_no_active_input_sets_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 && A2) && !(B1 && B2)) |-> Y
    );

// A high Y means all NOR inputs are inactive.
    check_y_high_implies_all_nor_inputs_inactive: assert property (
        @(posedge clk) Y |-> (!C1 && !(A1 && A2) && !(B1 && B2))
    );

// Reset clears the counter and deasserts overflow.
    check_reset_clears_state: assert property (
        @(posedge clk) reset |=> (count == 4'h0 && overflow == 1'b0)
    );

// When enabled below 15, the counter increments by one.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != 4'hF) |=> (count == ($past(count) + 4'd1))
    );

// When enabled at 15, the counter wraps to zero.
    check_count_wraps_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'hF) |=> (count == 4'h0)
    );

// When enabled below 15, overflow remains low.
    check_overflow_low_when_incrementing: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != 4'hF) |=> (overflow == 1'b0)
    );

// When enabled at 15, overflow is asserted on the next cycle.
    check_overflow_asserts_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'hF) |=> (overflow == 1'b1)
    );

// When not enabled, the counter holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// When not enabled, overflow holds its value.
    check_overflow_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (overflow == $past(overflow))
    );

// A_N high forces Y high.
    check_a_n_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B_N high forces Y high.
    check_b_n_forces_y_high: assert property (
        @(posedge clk) B_N |-> Y
    );

// Q_N is always the inverse of Q.
    check_qn_complement: assert property (
        @(posedge CLK) Q_N == ~Q
    );

// When SCE is high, Q captures SCD on the next clock.
    check_capture_scd_when_sce_high: assert property (
        @(posedge CLK) SCE |=> (Q == $past(SCD))
    );

// When SCE is low, Q captures D on the next clock.
    check_capture_d_when_sce_low: assert property (
        @(posedge CLK) !SCE |=> (Q == $past(D))
    );

// Q_N reflects the inverse of the captured input on the next clock.
    check_qn_matches_captured_input: assert property (
        @(posedge CLK) 1'b1 |=> (Q_N == ~($past(SCE) ? $past(SCD) : $past(D)))
    );

// X must match the implemented OR-then-AND function.
    check_output_function: assert property (
        @(posedge clk) X == (B1 & C1 & D1 & (A1 | A2))
    );

// B1 low must force X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low must force X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// D1 low must force X low.
    check_d1_low_forces_x_low: assert property (
        @(posedge clk) !D1 |-> !X
    );

// Both A inputs low must force X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// With all required terms high, X must be high.
    check_all_terms_high_drive_x_high: assert property (
        @(posedge clk) (B1 && C1 && D1 && (A1 || A2)) |-> X
    );

// A high X requires all required terms to be high.
    check_x_high_requires_all_terms_high: assert property (
        @(posedge clk) X |-> (B1 && C1 && D1 && (A1 || A2))
    );

// Up count wraps from 7 back to 0.
    check_up_wrap_from_max: assert property (
        @(posedge clk) (up_down == 1'b0 && q == 3'd7) |=> (q == 3'd0)
    );

// Up count increments by one when not at 7.
    check_up_increment: assert property (
        @(posedge clk) (up_down == 1'b0 && q != 3'd7) |=> (q == ($past(q) + 3'd1))
    );

// Down count wraps from 0 back to 7.
    check_down_wrap_from_zero: assert property (
        @(posedge clk) (up_down == 1'b1 && q == 3'd0) |=> (q == 3'd7)
    );

// Down count decrements by one when not at 0.
    check_down_decrement: assert property (
        @(posedge clk) (up_down == 1'b1 && q != 3'd0) |=> (q == ($past(q) - 3'd1))
    );

// Sum and carry-out equal 32-bit addition of a, b, and cin.
    check_total_sum: assert property (
        @(posedge CLK) {cout, sum} == ({1'b0, a} + {1'b0, b} + {31'b0, cin})
    );

// LSB sum equals XOR of a[0], b[0], and cin.
    check_lsb_sum: assert property (
        @(posedge CLK) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// If b is zero and cin is zero, sum equals a and carry-out is zero.
    check_b_zero_cin_zero: assert property (
        @(posedge CLK) (b == 32'h00000000 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// If a is zero and cin is zero, sum equals b and carry-out is zero.
    check_a_zero_cin_zero: assert property (
        @(posedge CLK) (a == 32'h00000000 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

// If a and b are zero, sum equals cin and carry-out is zero.
    check_ab_zero: assert property (
        @(posedge CLK) (a == 32'h00000000 && b == 32'h00000000) |-> (sum == {31'b0, cin} && cout == 1'b0)
    );

// If a and b are all zeros, sum equals cin and carry-out is zero.
    check_ab_zero_cin: assert property (
        @(posedge CLK) (a == 32'h00000000 && b == 32'h00000000) |-> (sum == {31'b0, cin} && cout == 1'b0)
    );

// Y matches the implemented OR-of-three function.
    check_output_function: assert property (
        @(posedge clk) Y == (A_N | B_N | ~(C & D))
    );

// A_N high forces Y high.
    check_a_n_forces_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B_N high forces Y high.
    check_b_n_forces_high: assert property (
        @(posedge clk) B_N |-> Y
    );

// C low forces Y high.
    check_c_low_forces_high: assert property (
        @(posedge clk) !C |-> Y
    );

// D low forces Y high.
    check_d_low_forces_high: assert property (
        @(posedge clk) !D |-> Y
    );

// A_N and B_N low with C and D high force Y low.
    check_all_terms_low_forces_low: assert property (
        @(posedge clk) (!A_N && !B_N && C && D) |-> !Y
    );

// Y low implies the A_N/B_N low and C/D high condition.
    check_low_output_condition: assert property (
        @(posedge clk) !Y |-> (!A_N && !B_N && C && D)
    );

// Y matches the implemented NOT/AND/NOR/BUF function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((~B1_N) | (A1 & A2))
    );

// A high A1 and A2 input force Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) ((A1 == 1'b1) && (A2 == 1'b1)) |-> (Y == 1'b0)
    );

// With B1_N high and A1 low, Y must be high.
    check_b1n_high_a1_low_y_high: assert property (
        @(posedge clk) ((B1_N == 1'b1) && (A1 == 1'b0)) |-> (Y == 1'b1)
    );

// With B1_N high and A2 low, Y must be high.
    check_b1n_high_a2_low_y_high: assert property (
        @(posedge clk) ((B1_N == 1'b1) && (A2 == 1'b0)) |-> (Y == 1'b1)
    );

// Y must equal the AND of all five inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & B1 & C1 & D1)
    );

// All five high inputs must drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A1 & A2 & B1 & C1 & D1) |-> Y
    );

// A low A1 input must force Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A low A2 input must force Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// A low B1 input must force Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// A low C1 input must force Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// A low D1 input must force Y low.
    check_d1_low_forces_y_low: assert property (
        @(posedge clk) !D1 |-> !Y
    );

// X must equal the OR of the two AND terms.
    check_x_matches_or_of_ands: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
    );

// A1 and A2 high must drive X high.
    check_a_term_drives_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// B1 and B2 high must drive X high.
    check_b_term_drives_x_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// With both AND terms low, X must be low.
    check_no_active_term_means_x_low: assert property (
        @(posedge clk) (!(A1 & A2) && !(B1 & B2)) |-> !X
    );

// X high must come from at least one active AND term.
    check_x_high_has_active_source: assert property (
        @(posedge clk) X |-> ((A1 & A2) || (B1 & B2))
    );

// out must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        out == ((sel1 & sel2) ? d3 :
                ((sel1 & ~sel2) ? d2 :
                 ((~sel1 & sel2) ? d1 : d0)))
    );

// When sel1 and sel2 are both high, out must select d3.
    check_select_d3: assert property (
        @(posedge clk)
        (sel1 && sel2) |-> (out == d3)
    );

// When sel1 is high and sel2 is low, out must select d2.
    check_select_d2: assert property (
        @(posedge clk)
        (sel1 && !sel2) |-> (out == d2)
    );

// When sel1 is low and sel2 is high, out must select d1.
    check_select_d1: assert property (
        @(posedge clk)
        (!sel1 && sel2) |-> (out == d1)
    );

// When both select bits are low, out must select d0.
    check_select_d0: assert property (
        @(posedge clk)
        (!sel1 && !sel2) |-> (out == d0)
    );

// out must match the RTL's comparison of the absolute values of A and B.
    check_out_matches_rtl: assert property (
        @(posedge clk) out == (|A > |B)
    );

// A with a greater magnitude than B must drive out high.
    check_a_greater_sets_out: assert property (
        @(posedge clk) (|A > |B) |-> (out == 1'b1)
    );

// A with a lesser or equal magnitude than B must drive out low.
    check_a_not_greater_clears_out: assert property (
        @(posedge clk) !(|A > |B) |-> (out == 1'b0)
    );

// Equal magnitudes must produce a low output.
    check_equal_magnitudes_clear_out: assert property (
        @(posedge clk) (|A == |B) |-> (out == 1'b0)
    );

// Reset clears dout on the next clock.
    check_reset_clears_dout: assert property (
        @(posedge clk) reset |=> (dout == 32'h00000000)
    );

// With ce low, dout holds its value.
    check_hold_when_ce_low: assert property (
        @(posedge clk) disable iff (reset) (!ce) |=> (dout == $past(dout))
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// Y matches the implemented NOR/AND/buffer function.
    check_output_function: assert property (
        @(posedge clk) Y == ((~A) & (~B) & C_N)
    );

// A high forces the NOR output low, so Y must be low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high forces the NOR output low, so Y must be low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C_N low forces the AND output low, so Y must be low.
    check_c_n_low_forces_y_low: assert property (
        @(posedge clk) !C_N |-> !Y
    );

// With both NOR inputs low and C_N high, Y must be high.
    check_active_inputs_drive_y_high: assert property (
        @(posedge clk) (!A && !B && C_N) |-> Y
    );

// A high Y requires both NOR inputs low and C_N high.
    check_y_high_requires_active_inputs: assert property (
        @(posedge clk) Y |-> (!A && !B && C_N)
    );

// With se low and rst high, q is cleared to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) disable iff (1'b0)
        (!se && rst) |=> (q == {SIZE{1'b0}})
    );

// Y matches the implemented NOR-of-ANDs function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force the NOR output low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// B1 and B2 high together force the NOR output low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// With no active NOR input term, Y must be high.
    check_no_active_term_drives_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 && A2) && !(B1 && B2)) |-> Y
    );

// A high Y means the C1 term is not active.
    check_y_high_excludes_c1_term: assert property (
        @(posedge clk) Y |-> !C1
    );

// A high Y means the A1/A2 term is not active.
    check_y_high_excludes_a_pair_term: assert property (
        @(posedge clk) Y |-> !(A1 && A2)
    );

// A high Y means the B1/B2 term is not active.
    check_y_high_excludes_b_pair_term: assert property (
        @(posedge clk) Y |-> !(B1 && B2)
    );

// When sel is low, out must equal a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When sel is high, out must equal b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// When sel is low, out captures in1 on the next clock.
    check_sel_low_captures_in1: assert property (
        @(posedge clk) (sel === 1'b0) |=> (out === $past(in1))
    );

// When sel is high, out captures in2 on the next clock.
    check_sel_high_captures_in2: assert property (
        @(posedge clk) (sel === 1'b1) |=> (out === $past(in2))
    );

// If both inputs are equal, out matches that common value on the next clock.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (in1 === in2) |=> (out === $past(in1))
    );

// Active-low reset forces the result to zero.
    check_reset_clears_result: assert property (
        @(posedge clk) !reset |-> (result == 4'b0000)
    );

// In add mode, result captures A + B on the next clock.
    check_add_mode_result: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b0) |=> (result == ($past(A) + $past(B)))
    );

// In subtract mode, result captures A - B on the next clock.
    check_sub_mode_result: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b1) |=> (result == ($past(A) - $past(B)))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// Load holds the previous count value.
    check_load_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(count))
    );

// Up mode increments the counter by one.
    check_up_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down) |=> (count == ($past(count) + 4'h1))
    );

// Down mode decrements the counter by one.
    check_down_decrements_count: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down) |=> (count == ($past(count) - 4'h1))
    );

// The counter value never exceeds 4'hF.
    check_count_within_range: assert property (
        @(posedge clk) disable iff (reset)
        (count <= 4'hF)
    );

// Synchronous reset clears the register on the next clock.
    check_reset_clears_out: assert property (
        @(posedge CLK) reset |=> (out == 4'd0)
    );

// When reset is low, out captures the previous cycle's in1+in2.
    check_loads_sum_when_not_reset: assert property (
        @(posedge CLK) disable iff (reset) 1'b1 |=> (out == ($past(in1) + $past(in2)))
    );

// X must equal the OR of A1, A2, and A3 gated by B1.
    check_x_matches_o31a_function: assert property (
        @(posedge clk) X == ((A1 | A2 | A3) & B1)
    );

// B1 low must force X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// All A inputs low must force X low.
    check_all_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2 && !A3) |-> !X
    );

// A1 high with B1 high must drive X high.
    check_a1_and_b1_drive_x_high: assert property (
        @(posedge clk) (A1 && B1) |-> X
    );

// A2 high with B1 high must drive X high.
    check_a2_and_b1_drive_x_high: assert property (
        @(posedge clk) (A2 && B1) |-> X
    );

// A3 high with B1 high must drive X high.
    check_a3_and_b1_drive_x_high: assert property (
        @(posedge clk) (A3 && B1) |-> X
    );

// X high requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires at least one A input to be high.
    check_x_high_requires_any_a_high: assert property (
        @(posedge clk) X |-> (A1 || A2 || A3)
    );

// Reset forces the counter to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

// The counter increments by one on each non-reset clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Reset forces the registered output to zero.
    check_reset_clears_sum: assert property (
        @(posedge clk) reset |-> (sum == 32'h00000000)
    );

// With select low, the output is the 32-bit sum of a and b.
    check_select_low_adds_inputs: assert property (
        @(posedge clk) disable iff (reset)
        (!select) |-> (sum == ((a + b) & 32'h00000000FFFFFFFF))
    );

// Zero on b passes a through when select is low.
    check_zero_b_passthrough: assert property (
        @(posedge clk) disable iff (reset)
        (!select && (b == 32'h00000000)) |-> (sum == a)
    );

// S captures the upper-nibble of m_payload_i_reg on awvalid.
    check_s_captures_upper_nibble: assert property (
        @(posedge aclk) si_rs_awvalid |=> (S == $past(m_payload_i_reg[47:44]))
    );

// S holds its value when awvalid is low.
    check_s_holds_without_awvalid: assert property (
        @(posedge aclk) !si_rs_awvalid |=> (S == $past(S))
    );

// m_axi_awaddr increments by axaddr_incr when axaddr_incr is non-zero.
    check_awaddr_increments_when_nonzero: assert property (
        @(posedge aclk) (axaddr_incr != 12'h000) |=> (m_axi_awaddr == ($past(m_axi_awaddr) + $past(axaddr_incr)))
    );

// m_axi_awaddr holds when axaddr_incr is zero.
    check_awaddr_holds_when_zero: assert property (
        @(posedge aclk) (axaddr_incr == 12'h000) |=> (m_axi_awaddr == $past(m_axi_awaddr))
    );

// In add mode, the upper 16 bits of result must be zero.
    check_add_mode_upper_zero: assert property (
        @(posedge clk) !sub |-> (result[31:16] == 16'h0000)
    );

// d_out_1 is the D input sampled on the previous rising edge.
    check_d_out_1_captures_d_in: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (d_out_1 == $past(d_in))
    );

// d_out_2 is the XOR of the previous d_out_1 and d_in.
    check_d_out_2_captures_toggle: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (d_out_2 == ($past(d_out_1) ^ $past(d_in)))
    );

// d_out_2 is the previous d_out_1 value.
    check_d_out_2_tracks_previous_d_out_1: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (d_out_2 == $past(d_out_1))
    );

// A low reset clears both outputs by the next rising edge.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        !reset |=> ((d_out_1 == 1'b0) && (d_out_2 == 1'b0))
    );

// EN high with A low must force Z low.
    check_en_high_a_low_forces_low: assert property (
        @(posedge clk) (EN && !A) |-> !Z
    );

// EN high with B low must force Z low.
    check_en_high_b_low_forces_low: assert property (
        @(posedge clk) (EN && !B) |-> !Z
    );

// Sum matches the XOR of the three inputs.
    check_sum_matches_xor: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry-out matches the implemented carry equation.
    check_carry_matches_and_or: assert property (
        @(posedge clk) Co == ((A & B) | ((A ^ B) & Ci))
    );

// Carry-out is high when both data inputs are high.
    check_carry_high_when_both_data_high: assert property (
        @(posedge clk) (A & B) |-> Co
    );

// Carry-out is high when the two data inputs differ and carry-in is high.
    check_carry_high_when_data_differs_and_cin_high: assert property (
        @(posedge clk) ((A ^ B) & Ci) |-> Co
    );

// Carry-out is low when the two data inputs differ and carry-in is low.
    check_carry_low_when_data_differs_and_cin_low: assert property (
        @(posedge clk) ((A ^ B) & !Ci) |-> !Co
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'h0)
    );

// Enable increments the counter by one when not in reset.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

// The counter holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Active-low clear forces the counter to zero.
    check_clear_forces_zero: assert property (
        @(posedge clk) !clear |-> (count_out == 4'b0000)
    );

// Load updates the counter with data_in on the next clock.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!clear)
        load |=> (count_out == $past(data_in))
    );

// Load has priority over up_down when both are asserted.
    check_load_priority_over_count: assert property (
        @(posedge clk) disable iff (!clear)
        (load && up_down) |=> (count_out == $past(data_in))
    );

// Count increments by one when load is low and up_down is high.
    check_increment_when_up: assert property (
        @(posedge clk) disable iff (!clear)
        (!load && up_down) |=> (count_out == ($past(count_out) + 4'b0001))
    );

// Count decrements by one when load is low and up_down is low.
    check_decrement_when_down: assert property (
        @(posedge clk) disable iff (!clear)
        (!load && !up_down) |=> (count_out == ($past(count_out) - 4'b0001))
    );

// Active-low reset forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge C) !R |-> (Q == 1'b0)
    );

// A sampled reset cycle leaves Q low on the next clock sample.
    check_reset_cycle_keeps_q_low: assert property (
        @(posedge C) (!R ##1 R) |-> (Q == 1'b0)
    );

// With reset inactive, Q matches the previous cycle's D value.
    check_q_follows_previous_d: assert property (
        @(posedge C) disable iff (!R) 1'b1 |=> (Q == $past(D))
    );

// Reset forces the counter to 000 on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 3'b000)
    );

// 001 advances to 010 on the next active cycle.
    check_state_001_to_010: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b001) |=> (out == 3'b010)
    );

// me_aluresult captures ex_aluresult on each non-reset cycle.
    check_aluresult_captured: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_aluresult == $past(ex_aluresult))
    );

// me_d2 captures ex_d2 on each non-reset cycle.
    check_d2_captured: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_d2 == $past(ex_d2))
    );

// me_td captures ex_td on each non-reset cycle.
    check_td_captured: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_td == $past(ex_td))
    );

// me_WREG captures ex_WREG on each non-reset cycle.
    check_wreg_captured: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_WREG == $past(ex_WREG))
    );

// me_WMEM captures ex_WMEM on each non-reset cycle.
    check_wmem_captured: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_WMEM == $past(ex_WMEM))
    );

// me_LW captures ex_LW on each non-reset cycle.
    check_lw_captured: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_LW == $past(ex_LW))
    );

// me_instr captures ex_instr on each non-reset cycle.
    check_instr_captured: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_instr == $past(ex_instr))
    );

// X matches the implemented OR-of-three function.
    check_x_matches_implemented_function: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A high forces X high.
    check_a_high_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_high_forces_x_high: assert property (
        @(posedge clk) B |-> X
    );

// With A and B low, X reduces to the NAND of C_N and D_N.
    check_ab_low_reduces_to_c_n_and_d_n_nand: assert property (
        @(posedge clk) (!A && !B) |-> (X == ~(C_N & D_N))
    );

// Sum and Cout are the registered 5-bit result of A + B + Cin.
    check_registered_result: assert property (
        @(posedge Clock) 1'b1 |=> ({Cout, Sum} == ({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)))
    );

// Sum is the low 4 bits of the registered result.
    check_sum_matches_result: assert property (
        @(posedge Clock) 1'b1 |=> (Sum == ($past(A) + $past(B) + $past(Cin)))
    );

// Cout is the carry-out bit of the registered result.
    check_cout_matches_result: assert property (
        @(posedge Clock) 1'b1 |=> (Cout == (({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)) >= 5'd16))
    );

// Adding zero with no carry-in leaves the inputs unchanged.
    check_zero_addition: assert property (
        @(posedge Clock) (B == 4'h0 && Cin == 1'b0) |=> ({Cout, Sum} == {1'b0, $past(A)})
    );

// A carry-in increments the zero result by one.
    check_cin_increments_zero: assert property (
        @(posedge Clock) (A == 4'h0 && B == 4'h0 && Cin == 1'b1) |=> ({Cout, Sum} == 5'h01)
    );

// The maximum input combination produces the maximum 5-bit result.
    check_max_input_case: assert property (
        @(posedge Clock) (A == 4'hF && B == 4'hF && Cin == 1'b1) |=> ({Cout, Sum} == 5'h1F)
    );

// Y matches the implemented A21OI function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// A1 and A2 high together force the AND term high and Y low.
    check_a1_a2_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1 low and A1 low, the AND term is low and Y is high.
    check_b1_low_a1_low_y_high: assert property (
        @(posedge clk) (!B1 && !A1) |-> Y
    );

// With B1 low and A2 low, the AND term is low and Y is high.
    check_b1_low_a2_low_y_high: assert property (
        @(posedge clk) (!B1 && !A2) |-> Y
    );

// Z must equal the AND of A, B, and C.
    check_and_function: assert property (
        @(posedge clk) Z == (A & B & C)
    );

// All three high inputs must drive Z high.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A && B && C) |-> Z
    );

// A low input must force Z low.
    check_a_low_forces_output_low: assert property (
        @(posedge clk) !A |-> !Z
    );

// B low input must force Z low.
    check_b_low_forces_output_low: assert property (
        @(posedge clk) !B |-> !Z
    );

// C low input must force Z low.
    check_c_low_forces_output_low: assert property (
        @(posedge clk) !C |-> !Z
    );

// out_mux selects data0 when sel is 0.
    check_out_mux_sel_0: assert property (
        @(posedge clk) (sel == 3'd0) |-> (out_mux == data0)
    );

// out_mux selects data1 when sel is 1.
    check_out_mux_sel_1: assert property (
        @(posedge clk) (sel == 3'd1) |-> (out_mux == data1)
    );

// out_mux selects data2 when sel is 2.
    check_out_mux_sel_2: assert property (
        @(posedge clk) (sel == 3'd2) |-> (out_mux == data2)
    );

// out_mux selects data3 when sel is 3.
    check_out_mux_sel_3: assert property (
        @(posedge clk) (sel == 3'd3) |-> (out_mux == data3)
    );

// out_mux selects data4 when sel is 4.
    check_out_mux_sel_4: assert property (
        @(posedge clk) (sel == 3'd4) |-> (out_mux == data4)
    );

// out_mux selects data5 when sel is 5.
    check_out_mux_sel_5: assert property (
        @(posedge clk) (sel == 3'd5) |-> (out_mux == data5)
    );

// out_mux drives zero when sel is 6 or 7.
    check_out_mux_default_zero: assert property (
        @(posedge clk) (sel >= 3'd6) |-> (out_mux == 4'b0000)
    );

// out_3bit mirrors sel.
    check_out_3bit_matches_sel: assert property (
        @(posedge clk) out_3bit == sel
    );

// o2 is the MSB of sel.
    check_o2_matches_sel_msb: assert property (
        @(posedge clk) o2 == sel[2]
    );

// o1 is the middle bit of sel.
    check_o1_matches_sel_mid: assert property (
        @(posedge clk) o1 == sel[1]
    );

// o0 is the LSB of sel.
    check_o0_matches_sel_lsb: assert property (
        @(posedge clk) o0 == sel[0]
    );

// Load captures the input vector into the register on the next cycle.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> (out == $past(in))
    );

// When not loading, the register rotates left by one bit.
    check_shift_rotates_register: assert property (
        @(posedge clk) !load |=> (out == { $past(out[2:0]), $past(out[3]) })
    );

// The serial output is the previous cycle's MSB.
    check_serial_output_tracks_msb: assert property (
        @(posedge clk) 1'b1 |=> (ser_out == $past(out[3]))
    );

// X must match the RTL Boolean equation.
    check_x_matches_rtl_equation: assert property (
        @(posedge clk)
        X == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))
    );

// When both A inputs are high and both B inputs are low, X must be high.
    check_x_high_when_a1_a2_high_and_b1_b2_low: assert property (
        @(posedge clk)
        (A1 & A2 & ~B1 & ~B2) |-> X
    );

// When both A inputs are low and both B inputs are high, X must be high.
    check_x_high_when_a1_a2_low_and_b1_b2_high: assert property (
        @(posedge clk)
        (~A1 & ~A2 & B1 & B2) |-> X
    );

// When the A and B input patterns do not match, X must be low.
    check_x_low_when_inputs_do_not_match: assert property (
        @(posedge clk)
        (!((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))) |-> !X
    );

// SEL=00 routes A to Y.
    check_sel_00_routes_a: assert property (
        @(posedge clk) (SEL == 2'b00) |-> (Y == A)
    );

// SEL=01 routes B to Y.
    check_sel_01_routes_b: assert property (
        @(posedge clk) (SEL == 2'b01) |-> (Y == B)
    );

// SEL=10 routes C to Y.
    check_sel_10_routes_c: assert property (
        @(posedge clk) (SEL == 2'b10) |-> (Y == C)
    );

// SEL=11 routes D to Y.
    check_sel_11_routes_d: assert property (
        @(posedge clk) (SEL == 2'b11) |-> (Y == D)
    );

// Q holds its value when the enable input is low.
    check_hold_when_disabled: assert property (
        @(posedge CK) !EN |=> (Q == $past(Q))
    );

// Q captures SE when the enable input is high.
    check_capture_when_enabled: assert property (
        @(posedge CK) EN |=> (Q == $past(SE))
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 8'h00)
    );

// The first sampled cycle after reset deassertion still shows zero.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (count == 8'h00)
    );

// The first active cycle after reset deassertion increments to one.
    check_post_reset_increment: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |=> (count == 8'h01)
    );

// The counter increments by one on each active clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 8'd1))
    );

// The 8-bit counter wraps from 255 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst) (count == 8'hFF) |=> (count == 8'h00)
    );

// out_valid is always equal to en.
    check_out_valid_matches_en: assert property (
        @(posedge clk) out_valid == en
    );

// out is high only when en is high and both inputs are high.
    check_out_matches_enabled_and: assert property (
        @(posedge clk) out == (en && in1 && in2)
    );

// out is low whenever en is low.
    check_out_low_when_en_low: assert property (
        @(posedge clk) !en |-> !out
    );

// out is low whenever in1 is low.
    check_out_low_when_in1_low: assert property (
        @(posedge clk) !in1 |-> !out
    );

// out is low whenever in2 is low.
    check_out_low_when_in2_low: assert property (
        @(posedge clk) !in2 |-> !out
    );

// out is high when en and both inputs are high.
    check_out_high_when_all_high: assert property (
        @(posedge clk) (en && in1 && in2) |-> out
    );

// O matches the implemented sum equation.
    check_o_matches_sum_equation: assert property (
        @(posedge clk) O == ((S & DI) | (~S & CI))
    );

// CO matches the implemented carry equation.
    check_co_matches_carry_equation: assert property (
        @(posedge clk) CO == (((CI & S) | (DI & (CI | S))))
    );

// When S is low, O follows CI.
    check_o_follows_ci_when_s_low: assert property (
        @(posedge clk) !S |-> (O == CI)
    );

// When S is high, O follows DI.
    check_o_follows_di_when_s_high: assert property (
        @(posedge clk) S |-> (O == DI)
    );

// With S low and CI low, O is low.
    check_o_low_when_s_low_and_ci_low: assert property (
        @(posedge clk) (!S && !CI) |-> !O
    );

// With S low and CI high, O is high.
    check_o_high_when_s_low_and_ci_high: assert property (
        @(posedge clk) (!S && CI) |-> O
    );

// With S high and DI low, O is low.
    check_o_low_when_s_high_and_di_low: assert property (
        @(posedge clk) (S && !DI) |-> !O
    );

// With S high and DI high, O is high.
    check_o_high_when_s_high_and_di_high: assert property (
        @(posedge clk) (S && DI) |-> O
    );

// ENCLK is low whenever reset is asserted.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RESET |-> (ENCLK == 1'b0)
    );

// ENCLK is low on the first clock after reset deasserts.
    check_reset_release_clears_enclk: assert property (
        @(posedge CLK) disable iff (RESET) $fell(RESET) |-> (ENCLK == 1'b0)
    );

// C must equal the bitwise AND of A and B.
    check_output_matches_and: assert property (
        @(posedge clk) C == (A & B)
    );

// C[0] must equal A[0] AND B[0].
    check_bit0_matches_and: assert property (
        @(posedge clk) C[0] == (A[0] & B[0])
    );

// C[1] must equal A[1] AND B[1].
    check_bit1_matches_and: assert property (
        @(posedge clk) C[1] == (A[1] & B[1])
    );

// C[2] must equal A[2] AND B[2].
    check_bit2_matches_and: assert property (
        @(posedge clk) C[2] == (A[2] & B[2])
    );

// C[3] must equal A[3] AND B[3].
    check_bit3_matches_and: assert property (
        @(posedge clk) C[3] == (A[3] & B[3])
    );

// C[4] must equal A[4] AND B[4].
    check_bit4_matches_and: assert property (
        @(posedge clk) C[4] == (A[4] & B[4])
    );

// C[5] must equal A[5] AND B[5].
    check_bit5_matches_and: assert property (
        @(posedge clk) C[5] == (A[5] & B[5])
    );

// C[6] must equal A[6] AND B[6].
    check_bit6_matches_and: assert property (
        @(posedge clk) C[6] == (A[6] & B[6])
    );

// C[7] must equal A[7] AND B[7].
    check_bit7_matches_and: assert property (
        @(posedge clk) C[7] == (A[7] & B[7])
    );

// Output is always one-hot or zero.
    check_out_onehot0: assert property (
        @(posedge clk) $onehot0(out)
    );

// Input 000 decodes to bit 0.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b00000001)
    );

// Input 001 decodes to bit 1.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b00000010)
    );

// Input 010 decodes to bit 2.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b00000100)
    );

// Input 011 decodes to bit 3.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b00001000)
    );

// Input 100 decodes to bit 4.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b00010000)
    );

// Input 101 decodes to bit 5.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b00100000)
    );

// Input 110 decodes to bit 6.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b01000000)
    );

// Input 111 decodes to bit 7.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b10000000)
    );

// A1, A2, and A3 high must drive X high.
    check_a1_a2_a3_sets_x: assert property (
        @(posedge clk)
        (A1 & A2 & A3) |-> X
    );

// A1, A2, and A4 high must drive X high.
    check_a1_a2_a4_sets_x: assert property (
        @(posedge clk)
        (A1 & A2 & A4) |-> X
    );

// A1, A3, and A4 high must drive X high.
    check_a1_a3_a4_sets_x: assert property (
        @(posedge clk)
        (A1 & A3 & A4) |-> X
    );

// A2, A3, and A4 high must drive X high.
    check_a2_a3_a4_sets_x: assert property (
        @(posedge clk)
        (A2 & A3 & A4) |-> X
    );

// A1, A2, and B1 high must drive X high.
    check_a1_a2_b1_sets_x: assert property (
        @(posedge clk)
        (A1 & A2 & B1) |-> X
    );

// A1, A3, and B1 high must drive X high.
    check_a1_a3_b1_sets_x: assert property (
        @(posedge clk)
        (A1 & A3 & B1) |-> X
    );

// A1, A4, and B1 high must drive X high.
    check_a1_a4_b1_sets_x: assert property (
        @(posedge clk)
        (A1 & A4 & B1) |-> X
    );

// A2, A3, and B1 high must drive X high.
    check_a2_a3_b1_sets_x: assert property (
        @(posedge clk)
        (A2 & A3 & B1) |-> X
    );

// A2, A4, and B1 high must drive X high.
    check_a2_a4_b1_sets_x: assert property (
        @(posedge clk)
        (A2 & A4 & B1) |-> X
    );

// A3, A4, and B1 high must drive X high.
    check_a3_a4_b1_sets_x: assert property (
        @(posedge clk)
        (A3 & A4 & B1) |-> X
    );

// In sign-extended mode, o must equal the 3-bit sum of the sign-extended inputs.
    check_sign_extended_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        SIGN_EXT |-> (o == {1'b0, a[WIDTH-1], a[WIDTH-2], a[WIDTH-3]} +
                           {1'b0, b[WIDTH-1], b[WIDTH-2], b[WIDTH-3]} +
                           {1'b0, c[WIDTH-1], c[WIDTH-2], c[WIDTH-3]})
    );

// In sign-extended mode, the upper two output bits must be zero.
    check_sign_extended_upper_bits_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        SIGN_EXT |-> (o[WIDTH+1:WIDTH] == 2'b00)
    );

// In sign-extended mode, the least-significant output bit must match a[WIDTH-3].
    check_sign_extended_lsb_from_a: assert property (
        @(posedge clk) disable iff (1'b0)
        SIGN_EXT |-> (o[0] == a[WIDTH-3])
    );

// Reset clears q on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 64'h0000000000000000)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && ld) |=> (q == 64'h0000000000000000)
    );

// Load captures d when reset is low.
    check_load_captures_d: assert property (
        @(posedge clk) disable iff (rst) ld |=> (q == $past(d))
    );

// q holds its value when neither reset nor load is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (rst) (!ld) |=> (q == $past(q))
    );

// Reset clears both trace outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !jrst_n |-> (atm == 36'h0) && (dtm == 36'h0)
    );

// A read cycle captures the address and read data.
    check_read_capture: assert property (
        @(posedge clk) disable iff (!jrst_n)
        cpu_d_read |=> (atm == {21'h0, $past(cpu_d_address)}) &&
                      (dtm == {32'h0, $past(cpu_d_readdata)})
    );

// A read and write cycle prioritize the read capture.
    check_read_over_write_priority: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (cpu_d_read && cpu_d_write) |=> (atm == {21'h0, $past(cpu_d_address)}) &&
                                      (dtm == {32'h0, $past(cpu_d_readdata)})
    );

// Without a read, write, or wait, the outputs hold their values.
    check_idle_holds_outputs: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && !cpu_d_write && !cpu_d_wait) |=> $stable({atm, dtm})
    );

// speed_select is loaded from data_in_r[16:15] on the final data sample.
    check_speed_select_load_on_final_sample: assert property (
        @(posedge mdio_mdc)
        (current_state == IDLE) && (data_counter == 6'h1f) &&
        (&data_in) && (data_in[31] == 1'b0) && (data_in[29:28] == 2'b10) &&
        (data_in[27:23] == 5'h10) && (data_in[22:18] == 5'h11)
        |=> (speed_select == $past(data_in_r[16:15]))
    );

// duplex_mode is loaded from data_in_r[14] on the final data sample.
    check_duplex_mode_load_on_final_sample: assert property (
        @(posedge mdio_mdc)
        (current_state == IDLE) && (data_counter == 6'h1f) &&
        (&data_in) && (data_in[31] == 1'b0) && (data_in[29:28] == 2'b10) &&
        (data_in[27:23] == 5'h10) && (data_in[22:18] == 5'h11)
        |=> (duplex_mode == $past(data_in_r[14]))
    );

// A low q forces q low on the next cycle.
    check_q_low_forces_q_low: assert property (
        @(posedge clk) !q |=> !q
    );

// Reset forces Q to zero on the next clock.
    check_reset_clears_q: assert property (
        @(posedge CK) RST |=> (Q == 4'h0)
    );

// When not in reset, Q increments by one each clock.
    check_increment_when_not_reset: assert property (
        @(posedge CK) disable iff (RST) 1'b1 |=> (Q == ($past(Q) + 4'd1))
    );

// The counter wraps from 15 back to 0.
    check_wrap_from_max: assert property (
        @(posedge CK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

// Y matches the implemented NOT-OR function.
    check_output_function: assert property (
        @(posedge clk) Y == (A_N | ~B)
    );

// A_N high forces Y high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) !B |-> Y
    );

// A_N low with B high forces Y low.
    check_low_input_combination_forces_y_low: assert property (
        @(posedge clk) (!A_N && B) |-> !Y
    );

// Y low implies the low-input combination is active.
    check_y_low_implies_low_input_combination: assert property (
        @(posedge clk) !Y |-> (!A_N && B)
    );

// Reset forces the FSM into IDLE.
    check_reset_state: assert property (
        @(posedge clk) !rst_n |-> (cur_state == 5'h1)
    );

// Reset forces the ASCII decode to "idle".
    check_reset_ascii: assert property (
        @(posedge clk) !rst_n |-> (cur_state_ascii == "idle")
    );

// AND operations drive the AND of a and b.
    check_and_operation: assert property (
        @(posedge clk)
        ((aluc == 4'b0001) || (aluc == 4'b1001)) |-> (result == (a & b))
    );

// OR operations drive the OR of a and b.
    check_or_operation: assert property (
        @(posedge clk)
        ((aluc == 4'b0101) || (aluc == 4'b1101)) |-> (result == (a | b))
    );

// XOR operations drive the XOR of a and b.
    check_xor_operation: assert property (
        @(posedge clk)
        ((aluc == 4'b1010) || (aluc == 4'b0010)) |-> (result == (a ^ b))
    );

// LUI operations drive the upper 16 bits of b.
    check_lui_operation: assert property (
        @(posedge clk)
        ((aluc == 4'b0110) || (aluc == 4'b1110)) |-> (result == {16'b0, b[15:0]})
    );

// ADD operations drive the 32-bit sum of a and b.
    check_add_operation: assert property (
        @(posedge clk)
        ((aluc == 4'b0000) || (aluc == 4'b1000)) |-> (result == (a + b))
    );

// SUB operations drive the 32-bit difference of a and b.
    check_sub_operation: assert property (
        @(posedge clk)
        ((aluc == 4'b0100) || (aluc == 4'b1100)) |-> (result == (a - b))
    );

// SLL operations drive b shifted left by a.
    check_sll_operation: assert property (
        @(posedge clk)
        (aluc == 4'b0011) |-> (result == (b << a))
    );

// SRL operations drive b shifted right by a.
    check_srl_operation: assert property (
        @(posedge clk)
        (aluc == 4'b0111) |-> (result == (b >> a))
    );

// When OE is high, Z10[1:0] must be 10.
    check_oe_high_lower_pair: assert property (
        @(posedge clk) OE |-> (Z10[1:0] == 2'b10)
    );

// When OE is low, Z10[1:0] must be 01.
    check_oe_low_lower_pair: assert property (
        @(posedge clk) !OE |-> (Z10[1:0] == 2'b01)
    );

// When OE is high, Z10[3:2] must be 01.
    check_oe_high_upper_pair: assert property (
        @(posedge clk) OE |-> (Z10[3:2] == 2'b01)
    );

// When OE is low, Z10[3:2] must be 10.
    check_oe_low_upper_pair: assert property (
        @(posedge clk) !OE |-> (Z10[3:2] == 2'b10)
    );

// The lower pair must always be the inverse of the upper pair.
    check_lower_pair_inverts_upper_pair: assert property (
        @(posedge clk) (Z10[1:0] == ~Z10[3:2])
    );

// A=00 passes D through unchanged.
    check_shift_00_passthrough: assert property (
        @(posedge clk) (A == 2'b00) |-> (S == D)
    );

// A=01 shifts D left by one and inserts 0 in bit 0.
    check_shift_01_left1_zero: assert property (
        @(posedge clk) (A == 2'b01) |-> (S == {D[2:0], 1'b0})
    );

// A=10 shifts D left by two and inserts 00 in bits [1:0].
    check_shift_10_left2_zero: assert property (
        @(posedge clk) (A == 2'b10) |-> (S == {D[1:0], 2'b00})
    );

// A=11 shifts D left by three and inserts 000 in bits [2:0].
    check_shift_11_left3_zero: assert property (
        @(posedge clk) (A == 2'b11) |-> (S == {D[0], 3'b000})
    );

// Y must always be the logical inverse of A.
    check_inverter_function: assert property (
        @(posedge clk) Y === ~A
    );

// A low input must produce a high output.
    check_low_input_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A high input must produce a low output.
    check_high_input_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// Z[0] and Z[1] are complementary.
    check_outputs_are_complementary: assert property (
        @(posedge clk) Z[0] != Z[1]
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// When enable is low, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// When enable is high, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// shifted_data[0] captures data[7] from the previous clock.
    check_shift_bit0_captures_data7: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[0] == $past(data[7]))
    );

// shifted_data[1] shifts in the previous shifted_data[0].
    check_shift_bit1_captures_prev_bit0: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[1] == $past(shifted_data[0]))
    );

// shifted_data[2] shifts in the previous shifted_data[1].
    check_shift_bit2_captures_prev_bit1: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[2] == $past(shifted_data[1]))
    );

// shifted_data[3] shifts in the previous shifted_data[2].
    check_shift_bit3_captures_prev_bit2: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[3] == $past(shifted_data[2]))
    );

// shifted_data[4] shifts in the previous shifted_data[3].
    check_shift_bit4_captures_prev_bit3: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[4] == $past(shifted_data[3]))
    );

// shifted_data[5] shifts in the previous shifted_data[4].
    check_shift_bit5_captures_prev_bit4: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[5] == $past(shifted_data[4]))
    );

// shifted_data[6] shifts in the previous shifted_data[5].
    check_shift_bit6_captures_prev_bit5: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[6] == $past(shifted_data[5]))
    );

// shifted_data[7] shifts in the previous shifted_data[6].
    check_shift_bit7_captures_prev_bit6: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[7] == $past(shifted_data[6]))
    );

// Y matches the implemented OR-then-NAND function.
    check_output_function: assert property (
        @(posedge clk) Y == ~(B1 & (A1 | A2 | A3))
    );

// A low B1 forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) !B1 |-> Y
    );

// All A inputs low force the OR term low and Y high.
    check_all_a_low_forces_y_high: assert property (
        @(posedge clk) (!A1 && !A2 && !A3) |-> Y
    );

// A high B1 with any A input high forces Y low.
    check_active_inputs_force_y_low: assert property (
        @(posedge clk) (B1 && (A1 || A2 || A3)) |-> !Y
    );

// A low Y requires B1 to be high and at least one A input high.
    check_y_low_has_valid_cause: assert property (
        @(posedge clk) !Y |-> (B1 && (A1 || A2 || A3))
    );

// Reset clears C on the next clock.
    check_reset_clears_c: assert property (
        @(posedge clk) rst |=> (C == 8'h00)
    );

// Outside reset, C captures the previous cycle's A+B.
    check_c_captures_sum: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (C == ($past(A) + $past(B)))
    );

// O must always be one-hot or zero.
    check_output_onehot0: assert property (
        @(posedge clk) $onehot0(O)
    );

// When A and B are both low, only O0 is high.
    check_decode_00: assert property (
        @(posedge clk) ({A, B} == 2'b00) |-> (O == 16'h0001)
    );

// When A is low and B is high, only O1 is high.
    check_decode_01: assert property (
        @(posedge clk) ({A, B} == 2'b01) |-> (O == 16'h0002)
    );

// When A is high and B is low, only O2 is high.
    check_decode_10: assert property (
        @(posedge clk) ({A, B} == 2'b10) |-> (O == 16'h0004)
    );

// When A and B are both high, only O3 is high.
    check_decode_11: assert property (
        @(posedge clk) ({A, B} == 2'b11) |-> (O == 16'h0008)
    );

// Active-low reset clears q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) !areset |-> (q == 4'b0000)
    );

// Load updates q with data on the next clock.
    check_load_updates_q: assert property (
        @(posedge clk) disable iff (!areset)
        load |=> (q == $past(data))
    );

// Load has priority over enable when both are asserted.
    check_load_priority_over_enable: assert property (
        @(posedge clk) disable iff (!areset)
        (load && ena) |=> (q == $past(data))
    );

// Enable rotates q left by one bit when load is low.
    check_enable_rotates_q: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && ena) |=> (q == { $past(q[2:0]), $past(q[3]) })
    );

// With no load or enable, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && !ena) |=> (q == $past(q))
    );

// When sel is low, out must equal a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When sel is high, out must equal b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// If both inputs are equal, out must match that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// X must match the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        X == ((A0 & ~S0 & ~S1) | (A1 & S0 & ~S1) | (A2 & ~S0 & S1) | (A3 & S0 & S1))
    );

// SUM is the XOR of A and B.
    check_sum_is_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// COUT is the AND of A and B.
    check_cout_is_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// Both low inputs produce a low sum and no carry.
    check_zero_inputs: assert property (
        @(posedge clk) (!A && !B) |-> (!SUM && !COUT)
    );

// A low and B high produce a high sum and no carry.
    check_a_low_b_high: assert property (
        @(posedge clk) (!A && B) |-> (SUM && !COUT)
    );

// A high and B low produce a high sum and no carry.
    check_a_high_b_low: assert property (
        @(posedge clk) (A && !B) |-> (SUM && !COUT)
    );

// Both high inputs produce a high carry and low sum.
    check_one_inputs: assert property (
        @(posedge clk) (A && B) |-> (COUT && !SUM)
    );

// X must equal A XOR B.
    check_xor_function: assert property (
        @(posedge clk) X == (A ^ B)
    );

// When A and B are equal, X must be low.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (A == B) |-> (X == 1'b0)
    );

// When A and B differ, X must be high.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (A != B) |-> (X == 1'b1)
    );

// A high X means the inputs differ.
    check_high_output_means_inputs_differ: assert property (
        @(posedge clk) (X == 1'b1) |-> (A != B)
    );

// A low X means the inputs are equal.
    check_low_output_means_inputs_equal: assert property (
        @(posedge clk) (X == 1'b0) |-> (A == B)
    );

// Y matches the implemented AND/NOR/BUF logic.
    check_y_matches_logic: assert property (
        @(posedge clk) Y == ~((A1 & A2 & B1) | (A1 & B1))
    );

// A1 low forces Y high.
    check_a1_low_forces_y_high: assert property (
        @(posedge clk) !A1 |-> Y
    );

// B1 low forces Y high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) !B1 |-> Y
    );

// A1 and B1 high force Y low.
    check_a1_b1_high_force_y_low: assert property (
        @(posedge clk) (A1 & B1) |-> !Y
    );

// A1, A2, and B1 high force Y low.
    check_all_three_high_force_y_low: assert property (
        @(posedge clk) (A1 & A2 & B1) |-> !Y
    );

// A1 and A2 high with B1 low force Y high.
    check_a1_a2_high_b1_low_force_y_high: assert property (
        @(posedge clk) (A1 & A2 & !B1) |-> Y
    );

// Reset clears the output on the next clock.
    check_reset_clears_data_out: assert property (
        @(posedge CLK) RST |=> (DATA_OUT == 8'h00)
    );

// Reset clears the stored partial products.
    check_reset_clears_result: assert property (
        @(posedge clk) reset |=> (result == 16'h0000)
    );

// out[1] is the previous cycle's in[3].
    check_out1_matches_previous_in3: assert property (
        @(posedge clk) 1'b1 |=> (out[1] == $past(in[3]))
    );

// Reset clears the internal state and forces the output low.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |-> ((data_sync == 2'b00) && (data_out == 1'b0))
    );

// Reset forces the state machine into S0.
    check_reset_state: assert property (
        @(posedge clk_i) !reset_n |-> (state == S0)
    );

// Reset forces the selected output to 000.
    check_reset_sel: assert property (
        @(posedge clk_i) !reset_n |-> (sel == 3'b000)
    );

// No RTL clock or reset; clk is a sampling clock for these checks.

    // shift_amount 00 passes data through unchanged.
    check_shift_00_passthrough: assert property (
        @(posedge clk) (shift_amount == 2'b00) |-> (result == data)
    );

// shift_amount 01 shifts data left by one and inserts 0 in bit 0.
    check_shift_01_left_by_one: assert property (
        @(posedge clk) (shift_amount == 2'b01) |-> (result == {data[2:0], 1'b0})
    );

// shift_amount 10 shifts data left by two and inserts 00 in bits [1:0].
    check_shift_10_left_by_two: assert property (
        @(posedge clk) (shift_amount == 2'b10) |-> (result == {data[1:0], 2'b00})
    );

// shift_amount 11 shifts data left by three and inserts 000 in bits [2:0].
    check_shift_11_left_by_three: assert property (
        @(posedge clk) (shift_amount == 2'b11) |-> (result == {data[0], 3'b000})
    );

// Result must be 00 when the inputs are equal.
    check_equal_maps_to_zero: assert property (
        @(posedge clk) (in0 == in1) |-> (result == 2'b00)
    );

// Result must be 01 when in0 is greater than in1.
    check_greater_maps_to_one: assert property (
        @(posedge clk) (in0 > in1) |-> (result == 2'b01)
    );

// Result must be 10 when in0 is less than in1.
    check_less_maps_to_two: assert property (
        @(posedge clk) (in0 < in1) |-> (result == 2'b10)
    );

// Result must never be 11.
    check_result_never_three: assert property (
        @(posedge clk) result != 2'b11
    );

// Result must match the RTL comparison function.
    check_result_matches_rtl_function: assert property (
        @(posedge clk) result == ((in0 > in1) ? 2'b01 : ((in0 < in1) ? 2'b10 : 2'b00))
    );

// Q follows D when DE is high.
    check_load_d_when_enabled: assert property (
        @(posedge CLK) DE |=> (Q == $past(D))
    );

// Q follows SCD when DE is low and SCE is high.
    check_load_scd_when_enabled: assert property (
        @(posedge CLK) (!DE && SCE) |=> (Q == $past(SCD))
    );

// Q holds its value when both enables are low.
    check_hold_when_disabled: assert property (
        @(posedge CLK) (!DE && !SCE) |=> (Q == $past(Q))
    );

// Y matches the implemented NAND/AND/buffer function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ((~(A2 & A1 & A3)) & (~(B2 & B1)))
    );

// All three A inputs high force Y low.
    check_a_triplet_forces_low: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> !Y
    );

// All two B inputs high force Y low.
    check_b_pair_forces_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// With no A-side high triplet and no B-side high pair, Y is high.
    check_no_active_inputs_drive_high: assert property (
        @(posedge clk) (!(A1 & A2 & A3) && !(B1 & B2)) |-> Y
    );

// A low Y must come from the A-side triplet or the B-side pair.
    check_low_output_has_cause: assert property (
        @(posedge clk) !Y |-> ((A1 & A2 & A3) || (B1 & B2))
    );

// A high Y means the A-side triplet is not active and the B-side pair is not active.
    check_high_output_means_no_active_inputs: assert property (
        @(posedge clk) Y |-> (!(A1 & A2 & A3) && !(B1 & B2))
    );

// D=0 maps to BCD=00000000.
    check_map_d0: assert property (
        @(posedge clk) (D == 4'h0) |-> (BCD == 8'h00)
    );

// D=1 maps to BCD=00000001.
    check_map_d1: assert property (
        @(posedge clk) (D == 4'h1) |-> (BCD == 8'h01)
    );

// D=2 maps to BCD=00000010.
    check_map_d2: assert property (
        @(posedge clk) (D == 4'h2) |-> (BCD == 8'h02)
    );

// D=3 maps to BCD=00000011.
    check_map_d3: assert property (
        @(posedge clk) (D == 4'h3) |-> (BCD == 8'h03)
    );

// D=4 maps to BCD=00000100.
    check_map_d4: assert property (
        @(posedge clk) (D == 4'h4) |-> (BCD == 8'h04)
    );

// D=5 maps to BCD=00000101.
    check_map_d5: assert property (
        @(posedge clk) (D == 4'h5) |-> (BCD == 8'h05)
    );

// D=6 maps to BCD=00000110.
    check_map_d6: assert property (
        @(posedge clk) (D == 4'h6) |-> (BCD == 8'h06)
    );

// D=7 maps to BCD=00000111.
    check_map_d7: assert property (
        @(posedge clk) (D == 4'h7) |-> (BCD == 8'h07)
    );

// D=8 maps to BCD=00001000.
    check_map_d8: assert property (
        @(posedge clk) (D == 4'h8) |-> (BCD == 8'h08)
    );

// D=9 maps to BCD=00001001.
    check_map_d9: assert property (
        @(posedge clk) (D == 4'h9) |-> (BCD == 8'h09)
    );

// D=10 maps to BCD=00010000.
    check_map_d10: assert property (
        @(posedge clk) (D == 4'hA) |-> (BCD == 8'h10)
    );

// D=11 maps to BCD=00010001.
    check_map_d11: assert property (
        @(posedge clk) (D == 4'hB) |-> (BCD == 8'h11)
    );

// D=12 maps to BCD=00010010.
    check_map_d12: assert property (
        @(posedge clk) (D == 4'hC) |-> (BCD == 8'h12)
    );

// D=13 maps to BCD=00010011.
    check_map_d13: assert property (
        @(posedge clk) (D == 4'hD) |-> (BCD == 8'h13)
    );

// D=14 maps to BCD=00010100.
    check_map_d14: assert property (
        @(posedge clk) (D == 4'hE) |-> (BCD == 8'h14)
    );

// D=15 maps to BCD=00010101.
    check_map_d15: assert property (
        @(posedge clk) (D == 4'hF) |-> (BCD == 8'h15)
    );

// SUM is the three-input XOR of A, B, and CI.
    check_sum_is_three_input_xor: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT is high when at least two inputs are high.
    check_cout_is_two_or_more_high: assert property (
        @(posedge clk) COUT == ((A & B) | (A & CI) | (B & CI))
    );

// COUT is low when fewer than two inputs are high.
    check_cout_is_zero_when_two_or_fewer_low: assert property (
        @(posedge clk) ((~A & ~B) | (~A & ~CI) | (~B & ~CI)) |-> !COUT
    );

// COUT is high when all three inputs are high.
    check_cout_is_one_when_all_high: assert property (
        @(posedge clk) (A & B & CI) |-> COUT
    );

// COUT is low when exactly one input is high.
    check_cout_is_zero_when_one_high: assert property (
        @(posedge clk) ((A & ~B & ~CI) | (~A & B & ~CI) | (~A & ~B & CI)) |-> !COUT
    );

// COUT is low when all three inputs are low.
    check_cout_is_zero_when_all_low: assert property (
        @(posedge clk) (~A & ~B & ~CI) |-> !COUT
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// A terminal count wraps back to zero on the next clock.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hF) |=> (count == 4'h0)
    );

// Non-terminal counts increment by one on the next clock.
    check_increment_from_nonmax: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'hF) |=> (count == ($past(count) + 4'h1))
    );

// The counter value is always zero or one more than the previous value.
    check_count_progression: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> ((count == 4'h0) || (count == ($past(count) + 4'h1)))
    );

// Y must always match the RTL's selected expression.
    check_output_matches_rtl: assert property (
        @(posedge clk) Y == (invert ? ~((~A) + 4'b0001) : ((~A) + 4'b0001))
    );

// In normal mode, Y must equal the inverted input plus one.
    check_normal_mode_output: assert property (
        @(posedge clk) !invert |-> (Y == ((~A) + 4'b0001))
    );

// In inverted mode, Y must equal the bitwise inverse of the inverted input plus one.
    check_inverted_mode_output: assert property (
        @(posedge clk) invert |-> (Y == ~((~A) + 4'b0001))
    );

// In normal mode, adding the output back to the input must wrap to zero.
    check_normal_mode_inverse_identity: assert property (
        @(posedge clk) !invert |-> ((Y + A) == 4'h0)
    );

// A low A_N and high B force Y low.
    check_low_a_n_and_high_b_drive_y_low: assert property (
        @(posedge clk) (!A_N && B) |-> !Y
    );

// out must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        out == ((sel1 & sel0) ? in3 :
                ((sel1 & ~sel0) ? in2 :
                 ((~sel1 & sel0) ? in1 : in0)))
    );

// When sel1 and sel0 are both high, out must select in3.
    check_select_in3: assert property (
        @(posedge clk)
        (sel1 && sel0) |-> (out == in3)
    );

// When sel1 is high and sel0 is low, out must select in2.
    check_select_in2: assert property (
        @(posedge clk)
        (sel1 && !sel0) |-> (out == in2)
    );

// When sel1 is low and sel0 is high, out must select in1.
    check_select_in1: assert property (
        @(posedge clk)
        (!sel1 && sel0) |-> (out == in1)
    );

// When sel1 and sel0 are both low, out must select in0.
    check_select_in0: assert property (
        @(posedge clk)
        (!sel1 && !sel0) |-> (out == in0)
    );

// oRD_BUSY is tied low.
    check_rd_busy_tied_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) oRD_BUSY == 1'b0
    );

// oRD_MMU_FLAGS is tied low.
    check_rd_mmu_flags_tied_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) oRD_MMU_FLAGS == 12'h000
    );

// oRD_VALID is cleared by reset, reset sync, or remove.
    check_rd_valid_clear_conditions: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (iRESET_SYNC || iREMOVE) |=> (oRD_VALID == 1'b0)
    );

// oRD_VALID is set by a read request when no clear condition is active.
    check_rd_valid_set_condition: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iREMOVE && iRD_REQ) |=> (oRD_VALID == 1'b1)
    );

// oRD_HIT is tied low.
    check_rd_hit_tied_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) oRD_HIT == 1'b0
    );

// oRD_DATA is tied low.
    check_rd_data_tied_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) oRD_DATA == 32'h0
    );

// oUP_BUSY is tied low.
    check_up_busy_tied_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) oUP_BUSY == 1'b0
    );

// oWR_BUSY is tied low.
    check_wr_busy_tied_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) oWR_BUSY == 1'b0
    );

// Output matches the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) out == ((~sel & in0) | (sel & in1))
    );

// When sel is low, the output follows in0.
    check_sel_low_routes_in0: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == in0)
    );

// When sel is high, the output follows in1.
    check_sel_high_routes_in1: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == in1)
    );

// A high output must come from at least one high input.
    check_out_high_requires_one_input_high: assert property (
        @(posedge clk) (out == 1'b1) |-> ((in0 == 1'b1) || (in1 == 1'b1))
    );

// X must match the RTL boolean equation.
    check_x_matches_rtl_equation: assert property (
        @(posedge clk)
        X == ((A && B) || (C || D) || !(E && F) || !(G || H))
    );

// A and B high must drive X high.
    check_ab_term_sets_x: assert property (
        @(posedge clk)
        (A && B) |-> X
    );

// C or D high must drive X high.
    check_cd_term_sets_x: assert property (
        @(posedge clk)
        (C || D) |-> X
    );

// E and F low must drive X high.
    check_ef_term_sets_x: assert property (
        @(posedge clk)
        (!(E && F)) |-> X
    );

// G and H low must drive X high.
    check_gh_term_sets_x: assert property (
        @(posedge clk)
        (!(G || H)) |-> X
    );

// X must be low when all four product terms are false.
    check_x_low_when_all_terms_false: assert property (
        @(posedge clk)
        (!((A && B) || (C || D) || !(E && F) || !(G || H))) |-> !X
    );

// X must be high when any one of the four product terms is true.
    check_x_high_when_any_term_true: assert property (
        @(posedge clk)
        ((A && B) || (C || D) || !(E && F) || !(G || H)) |-> X
    );

// Y must equal the NAND of A and B.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A & B)
    );

// Both high inputs must drive Y low.
    check_both_inputs_high_drive_low: assert property (
        @(posedge clk) (A && B) |-> !Y
    );

// A low must drive Y high.
    check_a_low_drives_high: assert property (
        @(posedge clk) !A |-> Y
    );

// B low must drive Y high.
    check_b_low_drives_high: assert property (
        @(posedge clk) !B |-> Y
    );

// A low output can only occur when both inputs are high.
    check_low_output_requires_both_inputs_high: assert property (
        @(posedge clk) !Y |-> (A && B)
    );

// y matches the implemented NAND-based XOR function.
    check_output_matches_implemented_function: assert property (
        @(posedge clk) y == ~((~a & ~b) | (a & b))
    );

// y is low when both inputs are low.
    check_output_low_when_both_inputs_low: assert property (
        @(posedge clk) (!a && !b) |-> !y
    );

// y is high when exactly one input is high.
    check_output_high_when_one_input_high: assert property (
        @(posedge clk) ((a && !b) || (!a && b)) |-> y
    );

// y is low when both inputs are high.
    check_output_low_when_both_inputs_high: assert property (
        @(posedge clk) (a && b) |-> !y
    );

// Reset forces the counter to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'hF) |=> (count == 4'h0)
    );

// gray_out[3] captures the previous cycle's binary_in[3].
    check_gray_bit3_capture: assert property (
        @(posedge clk) 1'b1 |=> (gray_out[3] == $past(binary_in[3]))
    );

// gray_out[2] captures the previous cycle's binary_in[3] XOR binary_in[2].
    check_gray_bit2_capture: assert property (
        @(posedge clk) 1'b1 |=> (gray_out[2] == ($past(binary_in[3]) ^ $past(binary_in[2])))
    );

// gray_out[1] captures the previous cycle's binary_in[2] XOR binary_in[1].
    check_gray_bit1_capture: assert property (
        @(posedge clk) 1'b1 |=> (gray_out[1] == ($past(binary_in[2]) ^ $past(binary_in[1])))
    );

// gray_out[0] captures the previous cycle's binary_in[1] XOR binary_in[0].
    check_gray_bit0_capture: assert property (
        @(posedge clk) 1'b1 |=> (gray_out[0] == ($past(binary_in[1]) ^ $past(binary_in[0])))
    );

// Y matches the implemented A21OI function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// A1 and A2 high together force the AND term high and Y low.
    check_a1_a2_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1 low and A1 low, the AND term is low and Y is high.
    check_b1_low_a1_low_y_high: assert property (
        @(posedge clk) (!B1 && !A1) |-> Y
    );

// With B1 low and A2 low, the AND term is low and Y is high.
    check_b1_low_a2_low_y_high: assert property (
        @(posedge clk) (!B1 && !A2) |-> Y
    );

// A low Y can only occur when B1 is high or the A1/A2 AND term is high.
    check_y_low_has_valid_cause: assert property (
        @(posedge clk) !Y |-> (B1 || (A1 && A2))
    );

// out_final must equal the AND of the two XOR terms.
    check_out_final_function: assert property (
        @(posedge clk) out_final == ((a ^ b) & (c ^ d))
    );

// If both XOR terms are high, out_final must be high.
    check_out_final_high_when_both_terms_high: assert property (
        @(posedge clk) ((a ^ b) & (c ^ d)) |-> out_final
    );

// If either XOR term is low, out_final must be low.
    check_out_final_low_when_any_term_low: assert property (
        @(posedge clk) (!((a ^ b) & (c ^ d))) |-> !out_final
    );

// A high out_final requires both XOR terms to be high.
    check_out_final_high_requires_both_terms_high: assert property (
        @(posedge clk) out_final |-> ((a ^ b) & (c ^ d))
    );

// A low out_final requires at least one XOR term to be low.
    check_out_final_low_requires_any_term_low: assert property (
        @(posedge clk) !out_final |-> (!((a ^ b) & (c ^ d)))
    );

// 0 maps to 0000.
    check_map_0: assert property (
        @(posedge clk) (in_value == 4'd0) |-> (out_value == 4'b0000)
    );

// 1 maps to 0001.
    check_map_1: assert property (
        @(posedge clk) (in_value == 4'd1) |-> (out_value == 4'b0001)
    );

// 2 maps to 0010.
    check_map_2: assert property (
        @(posedge clk) (in_value == 4'd2) |-> (out_value == 4'b0010)
    );

// 3 maps to 0011.
    check_map_3: assert property (
        @(posedge clk) (in_value == 4'd3) |-> (out_value == 4'b0011)
    );

// 4 maps to 0100.
    check_map_4: assert property (
        @(posedge clk) (in_value == 4'd4) |-> (out_value == 4'b0100)
    );

// 5 maps to 0101.
    check_map_5: assert property (
        @(posedge clk) (in_value == 4'd5) |-> (out_value == 4'b0101)
    );

// 6 maps to 0110.
    check_map_6: assert property (
        @(posedge clk) (in_value == 4'd6) |-> (out_value == 4'b0110)
    );

// 7 maps to 0111.
    check_map_7: assert property (
        @(posedge clk) (in_value == 4'd7) |-> (out_value == 4'b0111)
    );

// 8 maps to 1000.
    check_map_8: assert property (
        @(posedge clk) (in_value == 4'd8) |-> (out_value == 4'b1000)
    );

// 9 maps to 1001.
    check_map_9: assert property (
        @(posedge clk) (in_value == 4'd9) |-> (out_value == 4'b1001)
    );

// Reset clears the registered outputs on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> ((out == 16'sd0) && ($past(out) != 16'sd0))
    );

// X must equal the AND of A and SLEEP_B.
    check_x_matches_and_function: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// When SLEEP_B is low, X must be low.
    check_sleep_low_forces_x_low: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When A is low, X must be low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// When both inputs are high, X must be high.
    check_both_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A && SLEEP_B) |-> X
    );

// A high X requires both inputs to be high.
    check_x_high_requires_both_inputs_high: assert property (
        @(posedge clk) X |-> (A && SLEEP_B)
    );

// out matches the implemented mux tree.
    check_out_matches_mux_tree: assert property (
        @(posedge clk)
        out == (sel1 ? (sel0 ? in3 : in2) : (sel0 ? in1 : in0))
    );

// When sel1 is low, out selects between in0 and in1.
    check_sel1_low_selects_in0_in1: assert property (
        @(posedge clk)
        !sel1 |-> (out == (sel0 ? in1 : in0))
    );

// When sel1 is high, out selects between in2 and in3.
    check_sel1_high_selects_in2_in3: assert property (
        @(posedge clk)
        sel1 |-> (out == (sel0 ? in3 : in2))
    );

// When sel0 is low, out selects between in0 and in2.
    check_sel0_low_selects_in0_in2: assert property (
        @(posedge clk)
        !sel0 |-> (out == (sel1 ? in2 : in0))
    );

// When sel0 is high, out selects between in1 and in3.
    check_sel0_high_selects_in1_in3: assert property (
        @(posedge clk)
        sel0 |-> (out == (sel1 ? in3 : in1))
    );

// With sel1 low and sel0 low, out follows in0.
    check_sel10_selects_in0: assert property (
        @(posedge clk)
        (!sel1 && !sel0) |-> (out == in0)
    );

// With sel1 low and sel0 high, out follows in1.
    check_sel10_selects_in1: assert property (
        @(posedge clk)
        (!sel1 && sel0) |-> (out == in1)
    );

// With sel1 high and sel0 low, out follows in2.
    check_sel11_selects_in2: assert property (
        @(posedge clk)
        (sel1 && !sel0) |-> (out == in2)
    );

// With sel1 high and sel0 high, out follows in3.
    check_sel11_selects_in3: assert property (
        @(posedge clk)
        (sel1 && sel0) |-> (out == in3)
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 2'b00)
    );

// When enabled below 3, count increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst)
        (en && (count != 2'b11)) |=> (count == ($past(count) + 2'b01))
    );

// When enabled at 3, count wraps to zero.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (!rst)
        (en && (count == 2'b11)) |=> (count == 2'b00)
    );

// When disabled, count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst)
        (!en) |=> (count == $past(count))
    );

// Y must equal the AND of A, B, and C.
    check_y_matches_and: assert property (
        @(posedge clk) Y == (A & B & C)
    );

// A high Y requires all three inputs to be high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A && B && C)
    );

// All three high inputs must drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A && B && C) |-> Y
    );

// A low A must force Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// A low B must force Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// A low C must force Y low.
    check_c_low_forces_y_low: assert property (
        @(posedge clk) !C |-> !Y
    );

// Y must equal the AND of A, B, and C.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A & B & C)
    );

// All three high inputs must drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A && B && C) |-> Y
    );

// A low input must force Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// B low input must force Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// C low input must force Y low.
    check_c_low_forces_y_low: assert property (
        @(posedge clk) !C |-> !Y
    );

// Up increments Q by one when Q is not at 15.
    check_up_increments: assert property (
        @(posedge clk) Up && (Q != 4'hF) |=> (Q == ($past(Q) + 4'd1))
    );

// Up wraps Q from 15 back to 0.
    check_up_wraps: assert property (
        @(posedge clk) Up && (Q == 4'hF) |=> (Q == 4'h0)
    );

// Down decrements Q by one when Q is not at 0.
    check_down_decrements: assert property (
        @(posedge clk) Down && !Up && (Q != 4'h0) |=> (Q == ($past(Q) - 4'd1))
    );

// Down wraps Q from 0 back to 15.
    check_down_wraps: assert property (
        @(posedge clk) Down && !Up && (Q == 4'h0) |=> (Q == 4'hF)
    );

// Q holds its value when neither control is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) (!Up && !Down) |=> (Q == $past(Q))
    );

// Up has priority over Down when both are asserted.
    check_up_priority_over_down: assert property (
        @(posedge clk) Up && Down |=> (Q == ($past(Q) + 4'd1))
    );

// X matches the implemented OR-then-AND function.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2) & B1 & C1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// Both A inputs low force X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// X high requires B1 and C1 high.
    check_x_high_requires_b1_and_c1: assert property (
        @(posedge clk) X |-> (B1 && C1)
    );

// X high requires at least one A input high.
    check_x_high_requires_a1_or_a2: assert property (
        @(posedge clk) X |-> (A1 || A2)
    );

// X high requires both OR and AND terms to be true.
    check_x_high_requires_both_terms: assert property (
        @(posedge clk) X |-> (((A1 | A2) & B1) && C1)
    );

// I equal to 12'h001 drives O high.
    check_001_drives_o_high: assert property (
        @(posedge clk) (I == 12'h001) |-> (O == 1'b1)
    );

// I equal to 12'h002 drives O low.
    check_002_drives_o_low: assert property (
        @(posedge clk) (I == 12'h002) |-> (O == 1'b0)
    );

// I equal to 12'h004 drives O high.
    check_004_drives_o_high: assert property (
        @(posedge clk) (I == 12'h004) |-> (O == 1'b1)
    );

// I equal to 12'h008 drives O low.
    check_008_drives_o_low: assert property (
        @(posedge clk) (I == 12'h008) |-> (O == 1'b0)
    );

// I equal to 12'h010 drives O high.
    check_010_drives_o_high: assert property (
        @(posedge clk) (I == 12'h010) |-> (O == 1'b1)
    );

// I equal to 12'h020 drives O low.
    check_020_drives_o_low: assert property (
        @(posedge clk) (I == 12'h020) |-> (O == 1'b0)
    );

// I equal to 12'h040 drives O high.
    check_040_drives_o_high: assert property (
        @(posedge clk) (I == 12'h040) |-> (O == 1'b1)
    );

// I equal to 12'h080 drives O low.
    check_080_drives_o_low: assert property (
        @(posedge clk) (I == 12'h080) |-> (O == 1'b0)
    );

// I equal to 12'h100 drives O high.
    check_100_drives_o_high: assert property (
        @(posedge clk) (I == 12'h100) |-> (O == 1'b1)
    );

// I equal to 12'h200 drives O low.
    check_200_drives_o_low: assert property (
        @(posedge clk) (I == 12'h200) |-> (O == 1'b0)
    );

// I equal to 12'h400 drives O high.
    check_400_drives_o_high: assert property (
        @(posedge clk) (I == 12'h400) |-> (O == 1'b1)
    );

// I equal to 12'h800 drives O low.
    check_800_drives_o_low: assert property (
        @(posedge clk) (I == 12'h800) |-> (O == 1'b0)
    );

// I equal to 12'h000 drives O low.
    check_000_drives_o_low: assert property (
        @(posedge clk) (I == 12'h000) |-> (O == 1'b0)
    );

// I equal to 12'hFFF drives O low.
    check_fff_drives_o_low: assert property (
        @(posedge clk) (I == 12'hFFF) |-> (O == 1'b0)
    );

// X must equal the OR of the two 3-input AND terms.
    check_x_matches_or_of_ands: assert property (
        @(posedge clk) X == ((A1 & A2 & A3) | (B1 & B2))
    );

// A1, A2, and A3 high must drive X high.
    check_a_triplet_drives_x_high: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

// B1 and B2 high must drive X high.
    check_b_pair_drives_x_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// If neither AND term is true, X must be low.
    check_no_active_term_means_x_low: assert property (
        @(posedge clk) (!(A1 & A2 & A3) && !(B1 & B2)) |-> !X
    );

// X high must come from at least one active AND term.
    check_x_high_has_valid_source: assert property (
        @(posedge clk) X |-> ((A1 & A2 & A3) || (B1 & B2))
    );

// out matches the implemented NAND-of-NANDs function.
    check_out_matches_implemented_function: assert property (
        @(posedge clk) out == ~((~a) & (~b))
    );

// out is high when both inputs are high.
    check_out_high_when_both_inputs_high: assert property (
        @(posedge clk) (a && b) |-> out
    );

// out is low when both inputs are low.
    check_out_low_when_both_inputs_low: assert property (
        @(posedge clk) (!a && !b) |-> !out
    );

// out is high when a is high.
    check_out_high_when_a_high: assert property (
        @(posedge clk) a |-> out
    );

// out is high when b is high.
    check_out_high_when_b_high: assert property (
        @(posedge clk) b |-> out
    );

// X must equal the AND of all four inputs.
    check_and_function: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// All inputs high must drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// A low must force X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// B low must force X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low must force X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low must force X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// free3 and tm_count 11 select 0011.
    check_free3_tm11: assert property (
        @(posedge clk) (free3 && (tm_count == 2'b11)) |-> (fifowp_inc == 4'b0011)
    );

// free2 and tm_count 10 select 0010.
    check_free2_tm10: assert property (
        @(posedge clk) (free2 && (tm_count == 2'b10)) |-> (fifowp_inc == 4'b0010)
    );

// free2 and tm_count 00 select 0000.
    check_free2_tm00: assert property (
        @(posedge clk) (free2 && (tm_count == 2'b00)) |-> (fifowp_inc == 4'b0000)
    );

// No free and tm_count 01 select 0001.
    check_no_free_tm01: assert property (
        @(posedge clk) ((!free3) && (tm_count == 2'b01)) |-> (fifowp_inc == 4'b0001)
    );

// No free and tm_count 00 select 0000.
    check_no_free_tm00: assert property (
        @(posedge clk) ((!free3) && (tm_count == 2'b00)) |-> (fifowp_inc == 4'b0000)
    );

// free3 has priority over free2 when both are asserted.
    check_free3_priority: assert property (
        @(posedge clk) (free3 && free2 && (tm_count == 2'b11)) |-> (fifowp_inc == 4'b0011)
    );

// SUM matches A ^ B ^ ~CIN.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

// COUT matches the OR of the three AND terms.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

// When A and B are equal, SUM follows ~CIN.
    check_sum_when_ab_equal: assert property (
        @(posedge clk) (A == B) |-> (SUM == ~CIN)
    );

// When A and B differ, SUM follows CIN.
    check_sum_when_ab_different: assert property (
        @(posedge clk) (A != B) |-> (SUM == CIN)
    );

// When A and B are equal, COUT follows A.
    check_cout_when_ab_equal: assert property (
        @(posedge clk) (A == B) |-> (COUT == A)
    );

// When A and B differ, COUT follows ~CIN.
    check_cout_when_ab_different: assert property (
        @(posedge clk) (A != B) |-> (COUT == ~CIN)
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 2'b00)
    );

// Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 2'b00)
    );

// Enable increments the counter by one when not in reset.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 2'b01))
    );

// The counter holds its value when enable is low.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The counter wraps from 2'b11 back to 2'b00 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 2'b11)) |=> (count == 2'b00)
    );

// pr is a single-cycle pulse.
    check_pr_is_single_cycle: assert property (
        @(posedge lpf_int)
        pr |=> !pr
    );

// pr is never high on consecutive cycles.
    check_pr_not_back_to_back: assert property (
        @(posedge lpf_int)
        pr |=> !pr
    );

// Active-low reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'h0)
    );

// On the first clock after reset deasserts, count is still zero.
    check_post_reset_starts_from_zero: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == 4'h0)
    );

// When not in reset, count increments by one each clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// When not in reset, count wraps from 15 back to 0.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Reset clears the registered result on the next clock.
    check_reset_clears_result: assert property (
        @(posedge clk) reset |=> (result == 32'd0)
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// Reset has priority over load.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && load) |-> (count == 4'd0)
    );

// Load updates count with data on the next cycle.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (rst) load |=> (count == $past(data))
    );

// Without load, count increments by one on the next cycle.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (rst) !load |=> (count == ($past(count) + 4'd1))
    );

// Count wraps from 15 back to 0 when not loading.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst) (!load && (count == 4'hF)) |=> (count == 4'd0)
    );

// Reset clears the horizontal counter.
    check_reset_clears_h_count: assert property (
        @(posedge clk) rst |-> (h_count == 10'h000)
    );

// Reset clears the vertical counter.
    check_reset_clears_v_count: assert property (
        @(posedge clk) rst |-> (v_count == 10'h000)
    );

// Reset clears the RGB outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |-> ((r == 8'h00) && (g == 8'h00) && (b == 8'h00))
    );

// RGB outputs are zero when hsync or vsync is high.
    check_outputs_zero_when_sync_active: assert property (
        @(posedge clk) disable iff (rst)
        (hsync == 1'b1 || vsync == 1'b1) |-> ((r == 8'h00) && (g == 8'h00) && (b == 8'h00))
    );

// Y matches the implemented NAND/AND/buffer function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ((~(A1 & A2)) & (~(B1 & B2)))
    );

// A1 and A2 high forces Y low.
    check_a_pair_high_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> !Y
    );

// B1 and B2 high forces Y low.
    check_b_pair_high_forces_y_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// With both input pairs inactive, Y is high.
    check_both_pairs_inactive_drive_y_high: assert property (
        @(posedge clk) (!(A1 & A2) && !(B1 & B2)) |-> Y
    );

// A high Y means neither input pair is fully high.
    check_y_high_implies_no_active_pair: assert property (
        @(posedge clk) Y |-> (!(A1 & A2) && !(B1 & B2))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (reset && load) |=> (count == 4'b0000)
    );

// Load updates the counter with data_in on the next clock.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

// Without load, the counter increments by one on the next clock.
    check_increment_when_no_load: assert property (
        @(posedge clk) disable iff (reset) !load |=> (count == ($past(count) + 4'd1))
    );

// The counter wraps from 15 back to 0 when incrementing.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Reset clears all stages on the next clock.
    check_reset_clears_all: assert property (
        @(posedge shift_clk) reset |=> (q0 == 4'b0000 && q1 == 4'b0000 && q2 == 4'b0000 && q3 == 4'b0000)
    );

// q0 captures data_in on each non-reset clock.
    check_q0_captures_data_in: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q0 == $past(data_in))
    );

// q1 captures the previous q0 value on each non-reset clock.
    check_q1_captures_q0: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q1 == $past(q0))
    );

// q2 captures the previous q1 value on each non-reset clock.
    check_q2_captures_q1: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q2 == $past(q1))
    );

// q3 captures the previous q2 value on each non-reset clock.
    check_q3_captures_q2: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q3 == $past(q2))
    );

// q1 reflects data_in after two non-reset clocks.
    check_q1_two_clock_delay: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> ##1 (q1 == $past(data_in, 2))
    );

// q2 reflects data_in after three non-reset clocks.
    check_q2_three_clock_delay: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> ##2 (q2 == $past(data_in, 3))
    );

// q3 reflects data_in after four non-reset clocks.
    check_q3_four_clock_delay: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> ##3 (q3 == $past(data_in, 4))
    );

// Y must match the RTL mux equation.
    check_mux_function: assert property (
        @(posedge clk) Y === (SEL ? B : A)
    );

// When SEL is low, Y must select A.
    check_select_a: assert property (
        @(posedge clk) (SEL === 1'b0) |-> (Y === A)
    );

// When SEL is high, Y must select B.
    check_select_b: assert property (
        @(posedge clk) (SEL === 1'b1) |-> (Y === B)
    );

// If both inputs are equal, Y must match that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );

// Sum bit 2 uses the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) |
            (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
            (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
        ))
    );

// reset_n_sync must be low whenever reset_n is low.
    check_sync_low_during_reset: assert property (
        @(posedge clk) !reset_n |-> (reset_n_sync == {NUM_RESET_OUTPUT{1'b0}})
    );

// A sampled reset assertion must leave reset_n_sync high on the next clock.
    check_sync_high_after_reset_assert: assert property (
        @(posedge clk) $fell(reset_n) |-> (reset_n_sync == {NUM_RESET_OUTPUT{1'b1}})
    );

// reset_n_sync must remain stable while reset_n is held low.
    check_sync_stable_during_reset: assert property (
        @(posedge clk) (!reset_n && $past(!reset_n)) |-> (reset_n_sync == $past(reset_n_sync))
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'b0000)
    );

// Load updates count with data_in on the next cycle.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(data_in))
    );

// Load has priority over up_down when both are asserted.
    check_load_priority_over_up_down: assert property (
        @(posedge clk) disable iff (reset)
        (load && up_down) |=> (count == $past(data_in))
    );

// Count increments by one when load is low and up_down is high.
    check_increment_when_up: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// Count decrements by one when load is low and up_down is low.
    check_decrement_when_down: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

// Y must always be the logical inverse of A.
    check_inversion_function: assert property (
        @(posedge clk) Y === ~A
    );

// A low input must produce a high output.
    check_low_input_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A high input must produce a low output.
    check_high_input_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// blank forces all seven output LEDs on.
    check_blank_forces_all_on: assert property (
        @(posedge clk) blank |-> (s7 == 7'b1111111)
    );

// Y matches the implemented NAND/OR/NAND/BUF function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ~((~(A2_N & A1_N)) & (B2 | B1))
    );

// Both A inputs high force Y high.
    check_a_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A1_N & A2_N) |-> Y
    );

// Both B inputs low force Y high.
    check_b_inputs_low_drive_y_high: assert property (
        @(posedge clk) (!B1 & !B2) |-> Y
    );

// A1_N low with either B input high forces Y low.
    check_a1_low_with_b_high_drives_y_low: assert property (
        @(posedge clk) (!A1_N & (B1 | B2)) |-> !Y
    );

// A2_N low with either B input high forces Y low.
    check_a2_low_with_b_high_drives_y_low: assert property (
        @(posedge clk) (!A2_N & (B1 | B2)) |-> !Y
    );

// A1_N low with both B inputs low forces Y high.
    check_a1_low_with_b_low_drives_y_high: assert property (
        @(posedge clk) (!A1_N & !B1 & !B2) |-> Y
    );

// A2_N low with both B inputs low forces Y high.
    check_a2_low_with_b_low_drives_y_high: assert property (
        @(posedge clk) (!A2_N & !B1 & !B2) |-> Y
    );

// Reset forces the output to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 4'b0000)
    );

// Load captures the low 4 bits of data.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (out == $past(data[3:0]))
    );

// Load has priority over select.
    check_load_priority_over_select: assert property (
        @(posedge clk) disable iff (reset)
        (load && select) |=> (out == $past(data[3:0]))
    );

// Select rotates in left-to-right when load is low.
    check_select_rotates_left: assert property (
        @(posedge clk) disable iff (reset)
        (!load && select) |=> (out == {$past(in[2:0]), $past(in[3])})
    );

// Without load or select, the output rotates in right-to-left.
    check_default_rotates_right: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !select) |=> (out == {$past(in[0]), $past(in[3:1])})
    );

// 0 maps to 0000.
    check_map_0000000000: assert property (
        @(posedge clk) (input_val == 10'b0000000000) |-> (binary_val == 4'b0000)
    );

// 1 maps to 0001.
    check_map_0000000001: assert property (
        @(posedge clk) (input_val == 10'b0000000001) |-> (binary_val == 4'b0001)
    );

// 2 maps to 0010.
    check_map_0000000010: assert property (
        @(posedge clk) (input_val == 10'b0000000010) |-> (binary_val == 4'b0010)
    );

// 3 maps to 0011.
    check_map_0000000011: assert property (
        @(posedge clk) (input_val == 10'b0000000011) |-> (binary_val == 4'b0011)
    );

// 4 maps to 0100.
    check_map_0000000100: assert property (
        @(posedge clk) (input_val == 10'b0000000100) |-> (binary_val == 4'b0100)
    );

// 5 maps to 0101.
    check_map_0000000101: assert property (
        @(posedge clk) (input_val == 10'b0000000101) |-> (binary_val == 4'b0101)
    );

// 6 maps to 0110.
    check_map_0000000110: assert property (
        @(posedge clk) (input_val == 10'b0000000110) |-> (binary_val == 4'b0110)
    );

// 7 maps to 0111.
    check_map_0000000111: assert property (
        @(posedge clk) (input_val == 10'b0000000111) |-> (binary_val == 4'b0111)
    );

// 8 maps to 1000.
    check_map_0000001000: assert property (
        @(posedge clk) (input_val == 10'b0000001000) |-> (binary_val == 4'b1000)
    );

// 9 maps to 1001.
    check_map_0000001001: assert property (
        @(posedge clk) (input_val == 10'b0000001001) |-> (binary_val == 4'b1001)
    );

// Values above 9 map to 0000.
    check_map_default: assert property (
        @(posedge clk) (input_val >= 10'b0000001010) |-> (binary_val == 4'b0000)
    );

// A low A1 input forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) !A1 |-> !X
    );

// A low A2 input forces X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) !A2 |-> !X
    );

// A high B1_N input forces X low.
    check_b1n_high_forces_x_low: assert property (
        @(posedge clk) B1_N |-> !X
    );

// A high X requires A1 and A2 to be high and B1_N to be low.
    check_x_high_requires_inputs: assert property (
        @(posedge clk) X |-> (A1 && A2 && !B1_N)
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'h0)
    );

// The first sampled cycle after reset deassertion still shows zero.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (count == 4'h0)
    );

// The counter increments by one when below 9.
    check_increment_when_below_nine: assert property (
        @(posedge clk) disable iff (rst) (count != 4'h9) |=> (count == ($past(count) + 4'd1))
    );

// The counter wraps from 9 back to 0.
    check_wrap_from_nine_to_zero: assert property (
        @(posedge clk) disable iff (rst) (count == 4'h9) |=> (count == 4'h0)
    );

// The counter value never exceeds 9.
    check_count_range: assert property (
        @(posedge clk) disable iff (rst) (count <= 4'h9)
    );

// X must equal the RTL OR-of-ones function.
    check_x_matches_rtl_function: assert property (
        @(posedge clk) X == ~(A_N | B | C | D)
    );

// A_N high forces X low.
    check_an_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// B high forces X low.
    check_b_high_forces_x_low: assert property (
        @(posedge clk) B |-> !X
    );

// C high forces X low.
    check_c_high_forces_x_low: assert property (
        @(posedge clk) C |-> !X
    );

// D high forces X low.
    check_d_high_forces_x_low: assert property (
        @(posedge clk) D |-> !X
    );

// All inputs low produce X high.
    check_all_inputs_low_produces_x_high: assert property (
        @(posedge clk) (!A_N && !B && !C && !D) |-> X
    );

// X high implies all inputs are low.
    check_x_high_implies_all_inputs_low: assert property (
        @(posedge clk) X |-> (!A_N && !B && !C && !D)
    );

// Load captures data_in into data_out on the next clock.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> (data_out == $past(data_in))
    );

// Without load, data_out rotates left by one bit.
    check_shift_rotates_output: assert property (
        @(posedge clk) !load |=> (data_out == { $past(data_out[2:0]), $past(data_out[3]) })
    );

// The least-significant bit comes from the previous MSB when shifting.
    check_shift_wraps_msb_to_lsb: assert property (
        @(posedge clk) !load |=> (data_out[0] == $past(data_out[3]))
    );

// A zero input is captured when load is asserted.
    check_load_captures_zero_input: assert property (
        @(posedge clk) (load && (data_in == 4'h0)) |=> (data_out == 4'h0)
    );

// A zero output remains zero on the next clock when shifting.
    check_shift_keeps_zero_output: assert property (
        @(posedge clk) (!load && (data_out == 4'h0)) |=> (data_out == 4'h0)
    );

// Y must equal A & B & ~C.
    check_y_matches_function: assert property (
        @(posedge clk) Y == (A & B & ~C)
    );

// C high must force Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// A low must force Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// B low must force Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// With C low and both inputs high, Y must be high.
    check_all_inputs_true_drive_y_high: assert property (
        @(posedge clk) (!C && A && B) |-> Y
    );

// X must match the implemented OR-of-three function.
    check_output_function: assert property (
        @(posedge clk) X == ((A1 & A2) | B1 | C1)
    );

// B1 high must force X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// C1 high must force X high.
    check_c1_forces_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 high together must force X high.
    check_a1_a2_force_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// With B1 and C1 low, X must equal A1 AND A2.
    check_no_b1_c1_reduces_to_and: assert property (
        @(posedge clk) (!B1 && !C1) |-> (X == (A1 & A2))
    );

// With A1 and A2 low, X must equal B1 OR C1.
    check_no_a1_a2_reduces_to_or: assert property (
        @(posedge clk) (!A1 && !A2) |-> (X == (B1 | C1))
    );

// If X is low, then B1 and C1 must be low and not both A inputs high.
    check_x_low_implies_inputs: assert property (
        @(posedge clk) !X |-> (!B1 && !C1 && !(A1 && A2))
    );

// Y must always equal the XNOR of A and B.
    check_xnor_function: assert property (
        @(posedge clk) Y == ~(A ^ B)
    );

// When A and B are equal, Y must be high.
    check_equal_inputs_drive_high: assert property (
        @(posedge clk) (A == B) |-> (Y == 1'b1)
    );

// When A and B differ, Y must be low.
    check_different_inputs_drive_low: assert property (
        @(posedge clk) (A != B) |-> (Y == 1'b0)
    );

// gated_clk is low on the first clock after clk_en is low.
    check_gated_clk_low_after_en_low: assert property (
        @(posedge src_clk) !clk_en |=> !gated_clk
    );

// gated_clk is low on the second clock after clk_en is low.
    check_gated_clk_low_after_en_low_two_cycles: assert property (
        @(posedge src_clk) !clk_en |=> ##1 !gated_clk
    );

// Y must always match the mux equation.
    check_mux_function: assert property (
        @(posedge clk) Y === (SEL ? B : A)
    );

// When SEL is low, Y must equal A.
    check_select_a: assert property (
        @(posedge clk) (SEL === 1'b0) |-> (Y === A)
    );

// When SEL is high, Y must equal B.
    check_select_b: assert property (
        @(posedge clk) (SEL === 1'b1) |-> (Y === B)
    );

// If both inputs are equal, Y must equal that common value.
    check_equal_inputs: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );
